(function(){var m=window.SITE_DATA_BY_DOMAIN||{};var d=m["moe"]||{};var a=d["algorithms"]||[];for(var i=0;i<a.length;i++){if(a[i].id=="alg-capacity-factor-routing"){a[i]["long_html"]="<nav class=\"long-toc\"><b>本页目录</b><ol><li><button type=\"button\" class=\"toc-link\" data-sec=\"alg-capacity-factor-routing-sec-1\">一 · 一次 decode 长尾事故：热点专家把 All-to-All 缓冲撑爆</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"alg-capacity-factor-routing-sec-2\">二 · 容量公式与丢弃语义：把上界写成一行</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"alg-capacity-factor-routing-sec-3\">三 · 容量因子作为唯一旋钮：C=1.25 的含义</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"alg-capacity-factor-routing-sec-4\">四 · 长尾请求为何首当其冲：偏斜放大丢弃</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"alg-capacity-factor-routing-sec-5\">五 · 适用边界：什么时候该用，什么时候不该用</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"alg-capacity-factor-routing-sec-6\">六 · 容量因子路由的失效边界：从一次 decode P99 抖动事故说起</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"alg-capacity-factor-routing-sec-7\">七 · 请求切分与 token 预算落定</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"alg-capacity-factor-routing-sec-8\">八 · 路由打分与排序截断</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"alg-capacity-factor-routing-sec-9\">九 · 静态 dispatch 矩阵生成</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"alg-capacity-factor-routing-sec-10\">十 · All-to-All 发送与接收</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"alg-capacity-factor-routing-sec-11\">十一 · 分组 GEMM 与 combine 回填</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"alg-capacity-factor-routing-sec-12\">十二 · 容量因子的标定与漂移代价</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"alg-capacity-factor-routing-sec-13\">十三 · 容量因子失配时的失效链条与静态形状的隐性账单</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"alg-capacity-factor-routing-sec-14\">十四 · 容量因子失配时的系统账本：从 dispatch 矩阵到残差旁路的代价传导</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"alg-capacity-factor-routing-sec-15\">十五 · 容量公式的逐项解剖与量纲校验</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"alg-capacity-factor-routing-sec-16\">十六 · 从打分到截断：排序截断的等价形式</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"alg-capacity-factor-routing-sec-17\">十七 · 静态 dispatch 矩阵与缓冲上界的推导</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"alg-capacity-factor-routing-sec-18\">十八 · 固定 M 分组 GEMM 与 tcgen05 tile 的对齐</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"alg-capacity-factor-routing-sec-19\">十九 · 丢弃率与容量因子的标定方程</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"alg-capacity-factor-routing-sec-20\">二十 · 可实现性检查：从公式到 kernel 参数</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"alg-capacity-factor-routing-sec-21\">二十一 · 负载配方的三个自由度：token 预算、micro-batch 组成与容量因子</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"alg-capacity-factor-routing-sec-22\">二十二 · 适合的请求形态：短到中等长度、领域均匀、并发稳定</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"alg-capacity-factor-routing-sec-23\">二十三 · 长度分布不对时：重尾请求把 capacity 拖向两端</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"alg-capacity-factor-routing-sec-24\">二十四 · 领域分布不对时：长尾任务的专家偏斜击穿 C=1.25</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"alg-capacity-factor-routing-sec-25\">二十五 · 并发与批大小漂移：静态形状可预测，利用率却掉了</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"alg-capacity-factor-routing-sec-26\">二十六 · 负载配方错配时，静态形状反而成为负债</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"alg-capacity-factor-routing-sec-27\">二十七 · 硬件档位与并行拓扑的耦合约束</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"alg-capacity-factor-routing-sec-28\">二十八 · 量化方案与 capacity 的数值耦合</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"alg-capacity-factor-routing-sec-29\">二十九 · KV 策略与调度参数的联动</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"alg-capacity-factor-routing-sec-30\">三十 · 可复现配置思路：从 SLO 反推旋钮</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"alg-capacity-factor-routing-sec-31\">三十一 · 漂移监测与旋钮的在线调整边界</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"alg-capacity-factor-routing-sec-32\">三十二 · 容量因子标定之后：配方失效的三种边界与可复现的验证路径</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"alg-capacity-factor-routing-sec-33\">三十三 · 静态形状换来的吞吐：从 kernel launch 到 SM 占用</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"alg-capacity-factor-routing-sec-34\">三十四 · 显存与带宽：缓冲静态化的真实账</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"alg-capacity-factor-routing-sec-35\">三十五 · 通信拓扑：All-to-All 的尾延迟从哪来</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"alg-capacity-factor-routing-sec-36\">三十六 · 规模上去以后哪里先崩：三个次序</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"alg-capacity-factor-routing-sec-37\">三十七 · 吞吐与 SLO 的联合标定：把 C 当容量规划变量</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"alg-capacity-factor-routing-sec-38\">三十八 · 静态形状的账单：缓冲、带宽与尾延迟在何处先失衡</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"alg-capacity-factor-routing-sec-39\">三十九 · 静态容量在规模放大后的先崩点：缓冲、利用率与长尾</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"alg-capacity-factor-routing-sec-40\">四十 · 精度漂移：丢弃不是随机噪声，而是有偏采样</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"alg-capacity-factor-routing-sec-41\">四十一 · OOM 与缓冲膨胀：静态形状不等于静态显存</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"alg-capacity-factor-routing-sec-42\">四十二 · 批抖动与路由不均：吞吐不达预期的两个来源</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"alg-capacity-factor-routing-sec-43\">四十三 · 尾延迟尖刺：P99 可预测的前提被打破时</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"alg-capacity-factor-routing-sec-44\">四十四 · 监控面与回滚：把单一旋钮变成可观测闭环</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"alg-capacity-factor-routing-sec-45\">四十五 · 容量因子失配后的四类现场故障与回滚路径</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"alg-capacity-factor-routing-sec-46\">四十六 · 同族算法选型的第一性判据</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"alg-capacity-factor-routing-sec-47\">四十七 · 决策表：按负载形态与 SLO 落位</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"alg-capacity-factor-routing-sec-48\">四十八 · 与专家选择路由的边界：因果性与排序成本</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"alg-capacity-factor-routing-sec-49\">四十九 · 与块稀疏分组 GEMM 的边界：padding 的算力账</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"alg-capacity-factor-routing-sec-50\">五十 · 适用条件的形式化与标定流程</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"alg-capacity-factor-routing-sec-51\">五十一 · 选型的工程判断落点</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"alg-capacity-factor-routing-sec-52\">五十二 · 与相邻算法对照：容量因子路由的选型边界与失效条件</button></li></ol></nav><figure class=\"diagram\" data-fig=\"algo-flow\"><svg style=\"max-width:511px;margin:0 auto\" xmlns=\"http://www.w3.org/2000/svg\" viewBox=\"0 0 510.7 352\" preserveAspectRatio=\"xMidYMid meet\" role=\"img\"><rect x=\"58.0\" y=\"12.0\" width=\"428.7\" height=\"44.8\" rx=\"8\" fill=\"#fdf3e3\" stroke=\"#ecd9b8\" stroke-width=\"1.2\"/><circle cx=\"26\" cy=\"34.4\" r=\"12\" fill=\"#1f4e79\"/><text x=\"26.0\" y=\"38.6\" font-family=\"-apple-system,'PingFang SC','Noto Sans SC','Microsoft YaHei',sans-serif\" font-size=\"11.5\" fill=\"#ffffff\" font-weight=\"700\" text-anchor=\"middle\">1</text><text x=\"75.0\" y=\"39.6\" font-family=\"-apple-system,'PingFang SC','Noto Sans SC','Microsoft YaHei',sans-serif\" font-size=\"13.0\" fill=\"#0f1720\" font-weight=\"600\" text-anchor=\"start\">请求进入调度器后被切成固定 token 预算的 micro-batch，路…</text><line x1=\"82.0\" y1=\"58.8\" x2=\"82.0\" y2=\"75.8\" stroke=\"#d8d3c6\" stroke-width=\"1.4\"/><path d=\"M 77.5 74.8 L 86.5 74.8 L 82.0 82.8 Z\" fill=\"#d8d3c6\"/><rect x=\"58.0\" y=\"82.8\" width=\"428.7\" height=\"44.8\" rx=\"8\" fill=\"#ffffff\" stroke=\"#d8d3c6\" stroke-width=\"1.2\"/><circle cx=\"26\" cy=\"105.3\" r=\"12\" fill=\"#1f4e79\"/><text x=\"26.0\" y=\"109.5\" font-family=\"-apple-system,'PingFang SC','Noto Sans SC','Microsoft YaHei',sans-serif\" font-size=\"11.5\" fill=\"#ffffff\" font-weight=\"700\" text-anchor=\"middle\">2</text><text x=\"75.0\" y=\"110.5\" font-family=\"-apple-system,'PingFang SC','Noto Sans SC','Microsoft YaHei',sans-serif\" font-size=\"13.0\" fill=\"#0f1720\" font-weight=\"600\" text-anchor=\"start\">按打分排序后为每个专家截断到 capacity，溢出 token 标记为 …</text><line x1=\"82.0\" y1=\"129.7\" x2=\"82.0\" y2=\"146.7\" stroke=\"#d8d3c6\" stroke-width=\"1.4\"/><path d=\"M 77.5 145.7 L 86.5 145.7 L 82.0 153.7 Z\" fill=\"#d8d3c6\"/><rect x=\"58.0\" y=\"153.7\" width=\"428.7\" height=\"44.8\" rx=\"8\" fill=\"#ffffff\" stroke=\"#d8d3c6\" stroke-width=\"1.2\"/><circle cx=\"26\" cy=\"176.1\" r=\"12\" fill=\"#1f4e79\"/><text x=\"26.0\" y=\"180.3\" font-family=\"-apple-system,'PingFang SC','Noto Sans SC','Microsoft YaHei',sans-serif\" font-size=\"11.5\" fill=\"#ffffff\" font-weight=\"700\" text-anchor=\"middle\">3</text><text x=\"75.0\" y=\"181.3\" font-family=\"-apple-system,'PingFang SC','Noto Sans SC','Microsoft YaHei',sans-serif\" font-size=\"13.0\" fill=\"#0f1720\" font-weight=\"600\" text-anchor=\"start\">根据 capacity 生成静态的 dispatch 矩阵（token→专…</text><line x1=\"82.0\" y1=\"200.5\" x2=\"82.0\" y2=\"217.5\" stroke=\"#d8d3c6\" stroke-width=\"1.4\"/><path d=\"M 77.5 216.5 L 86.5 216.5 L 82.0 224.5 Z\" fill=\"#d8d3c6\"/><rect x=\"58.0\" y=\"224.5\" width=\"428.7\" height=\"44.8\" rx=\"8\" fill=\"#ffffff\" stroke=\"#d8d3c6\" stroke-width=\"1.2\"/><circle cx=\"26\" cy=\"247.0\" r=\"12\" fill=\"#1f4e79\"/><text x=\"26.0\" y=\"251.2\" font-family=\"-apple-system,'PingFang SC','Noto Sans SC','Microsoft YaHei',sans-serif\" font-size=\"11.5\" fill=\"#ffffff\" font-weight=\"700\" text-anchor=\"middle\">4</text><text x=\"75.0\" y=\"252.2\" font-family=\"-apple-system,'PingFang SC','Noto Sans SC','Microsoft YaHei',sans-serif\" font-size=\"13.0\" fill=\"#0f1720\" font-weight=\"600\" text-anchor=\"start\">专家侧按固定 M=capacity 的分组 GEMM 计算，tcgen05…</text><line x1=\"82.0\" y1=\"271.4\" x2=\"82.0\" y2=\"288.4\" stroke=\"#d8d3c6\" stroke-width=\"1.4\"/><path d=\"M 77.5 287.4 L 86.5 287.4 L 82.0 295.4 Z\" fill=\"#d8d3c6\"/><rect x=\"58.0\" y=\"295.4\" width=\"428.7\" height=\"44.8\" rx=\"8\" fill=\"#e8f5ec\" stroke=\"#cde9d5\" stroke-width=\"1.2\"/><circle cx=\"26\" cy=\"317.8\" r=\"12\" fill=\"#1f4e79\"/><text x=\"26.0\" y=\"322.0\" font-family=\"-apple-system,'PingFang SC','Noto Sans SC','Microsoft YaHei',sans-serif\" font-size=\"11.5\" fill=\"#ffffff\" font-weight=\"700\" text-anchor=\"middle\">5</text><text x=\"75.0\" y=\"323.0\" font-family=\"-apple-system,'PingFang SC','Noto Sans SC','Microsoft YaHei',sans-serif\" font-size=\"13.0\" fill=\"#0f1720\" font-weight=\"600\" text-anchor=\"start\">combine 阶段按原路由权重加权回填，dropped token 使用…</text></svg><figcaption><b>执行流程</b> · 从输入到输出的关键步骤；每一步的复杂度与坑在正文展开。</figcaption></figure>\n<h3 id=\"alg-capacity-factor-routing-sec-1\">一 · 一次 decode 长尾事故：热点专家把 All-to-All 缓冲撑爆</h3>\n<p>先把场景钉死：一个 MoE 解码服务，micro-batch 内 token 数随请求到达节奏波动，路由器对每个 token 取 top-k 专家。某个时段进来一批高度同质的请求——同一段代码补全的多个候选、同一道数学题的多种解法——它们的隐状态在路由空间里几乎重合，top-k 打分把绝大多数 token 压到同几个专家上。没有容量约束时，dispatch 阶段要为每个专家准备接收缓冲，缓冲大小必须按「最坏情况该专家可能收到的 token 数」来开，而这个最坏情况在运行时才知道。于是出现典型的连锁反应：热点专家的发送缓冲在 kernel launch 前无法定尺寸，只能走动态分配或按上限预留；动态分配引入 host 侧同步与显存碎片，按上限预留则在正常批次里浪费大量显存。更致命的是分组 GEMM 的 M 维随批次变化，tcgen05 的 tile 形状被迫在运行时重排，kernel 反复重编译或退化到低效模板，单层时延从稳定值跳到数倍。</p>\n<p>这就是本算法要解决的推理问题：<strong>在不改模型、不动路由打分的前提下，把每个专家的 token 数压到一个编译期可确定的上界</strong>。事故的根因不是算力不够，而是形状不可预测——All-to-All 缓冲膨胀与 GEMM 形状抖动共同制造了 decode 阶段的 P99 长尾。注意边界：它不解决路由质量问题（专家选择是否合理是路由器的职责），不解决专家并行通信带宽本身不足，也不解决权重与 KV cache 争抢显存的问题；它只把「负载波动」这一个变量从运行时赶到编译期。</p>\n\n<h3 id=\"alg-capacity-factor-routing-sec-2\">二 · 容量公式与丢弃语义：把上界写成一行</h3>\n<p>机制的核心是一条容量约束。给定 micro-batch 内 token 数 <em>T</em>、专家数 <em>E</em>、单一可调旋钮 capacity_factor，每专家接收上界为：</p>\n<div class=\"formula\">$$\\text{capacity}=\\left\\lceil \\text{capacity\\_factor}\\times\\frac{T}{E} \\right\\rceil,\\quad \\text{drop rate}=\\frac{1}{T}\\sum_{t=1}^{T}\\mathbb{1}\\left[\\text{rank}_e(t)&gt;\\text{capacity}\\right]$$</div>\n<p>第二个式子给出丢弃率的定义：对每个 token，若它在其目标专家上的排序位次超过 capacity，即计为丢弃。执行上分三步。其一，调度器把请求切成固定 token 预算的 micro-batch，路由器算 top-k 打分；其二，按打分排序后对每个专家截断到 capacity，溢出 token 标记为 dropped；其三，据 capacity 生成静态 dispatch 矩阵（token 到专家槽位），All-to-All 发送缓冲大小在 kernel launch 前即确定，专家侧按固定 M=capacity 的分组 GEMM 计算，tcgen05 的 tile 形状无需运行时重排。combine 阶段按原路由权重加权回填，dropped token 直接用残差输出进入下一层——这是「旁路」而非「置零」，保证残差流不断。</p>\n<p>代价立刻显现：被丢弃的 token 少经过一次专家变换，等于在该层注入了近似误差，直接损失模型质量。系统侧收益则是形状静态化——发送缓冲、GEMM 的 M 维、tile 形状全部在编译期锁定，避免运行时动态分配与 kernel 重编译，decode 的 P99 时延变得可预测。这是一个显式的交换：用可控的质量损失换可预测的尾延迟。</p>\n\n<h3 id=\"alg-capacity-factor-routing-sec-3\">三 · 容量因子作为唯一旋钮：C=1.25 的含义</h3>\n<p>capacity_factor 是整个算法唯一的调节点，它把 SLO 与质量放在同一根轴上。取 C=1.25 意味着每专家允许接收平均负载的 1.25 倍；材料给出的经验是此时 drop rate 通常低于 1%。这个数字要这样读：它不是保证，而是负载分布相对均匀时的典型值；一旦批次内专家偏斜加剧，同样的 C 会让 drop rate 抬升。C 偏小则丢弃增多、长尾请求质量骤降；C 偏大则 All-to-All 缓冲与显存按更大上界预留，正常批次里专家利用率下降、吞吐不达预期。</p>\n<table class=\"mini\"><thead><tr><th>容量因子取向</th><th>形状与显存</th><th>质量</th><th>尾延迟</th></tr></thead><tbody><tr><td>C 偏小</td><td>缓冲与 GEMM 形状紧凑，显存占用低</td><td>drop rate 升高，长尾请求受损明显</td><td>P99 稳定但输出不可控</td></tr><tr><td>C=1.25（典型标定）</td><td>缓冲按 1.25 倍均值预留</td><td>drop rate 通常 &lt;1%</td><td>P99 可预测</td></tr><tr><td>C 偏大</td><td>缓冲膨胀，专家槽位大量空置</td><td>几乎不丢</td><td>P99 稳定但吞吐被浪费的槽位拖低</td></tr></tbody></table>\n<p>工程判断在于：C 必须按负载分布离线标定，而不是拍脑袋取整。标定要覆盖真实流量的专家偏斜谱，尤其是代码与数学这类长尾请求的占比。流量分布漂移后，离线标定的 C 会失配——这是本算法最本质的规模上限约束，材料未给出具体专家数上限，但约束条件是负载分布的稳定性而非硬件规格。</p>\n\n<h3 id=\"alg-capacity-factor-routing-sec-4\">四 · 长尾请求为何首当其冲：偏斜放大丢弃</h3>\n<p>丢弃不是均匀发生的。代码补全与数学推理的 token 在路由空间中高度聚集，同一批请求内部的专家偏斜远高于通用对话。当这些请求恰好构成一个 micro-batch 的主体时，热点专家的排序位次迅速越过 capacity，drop rate 显著高于均值。后果不是均匀的精度下降，而是<strong>特定请求类型的输出质量不可控</strong>：dropped token 走残差旁路，等于该 token 跳过了一层专家计算，对需要精确符号操作的代码与多步推理的数学题，这种跳过会累积成可见的错误。</p>\n<p>系统侧的表现同样不对称：这些请求的 decode 步数往往更长，长尾时延本就吃紧，而它们恰恰是最容易被丢弃的一类。于是出现一个悖论——算法为可预测 P99 而生，却对最需要稳定质量的长尾请求最不友好。缓解手段只能在调度层做：按请求类型或路由熵给 micro-batch 分组，避免高偏斜请求独占一个批次；或对长尾请求单独放宽 C，代价是那部分批次的缓冲与显存按更大上界预留。这不是算法内部的修复，而是部署配方的一部分。</p>\n\n<h3 id=\"alg-capacity-factor-routing-sec-5\">五 · 适用边界：什么时候该用，什么时候不该用</h3>\n<p>适用条件可以收敛成三条。其一，decode 阶段的 P99 是硬 SLO，而负载波动导致形状不可预测是当前瓶颈；其二，负载分布在可接受的时间尺度内稳定，离线标定的 C 不会迅速失配；其三，业务能容忍低比例的 token 丢弃，且丢弃集中在非关键路径上。满足这三条时，容量因子路由用一行公式换来编译期静态的 dispatch 矩阵与分组 GEMM 形状，收益直接体现在尾延迟与 kernel 稳定性上。</p>\n<p>不适用或需换路的情形同样清楚。若质量不可妥协——例如长尾请求占比高且对丢弃零容忍——应转向无丢弃块稀疏分组 GEMM，用块级 padding 替代 token 丢弃；若愿意以破坏因果性为代价换取每专家负载恒等于 k、彻底无丢弃，则是专家选择路由的方向。这两条相邻路线各自解决「丢弃」的不同侧面，本算法明确选择以丢弃换静态形状与可预测 P99，因此它的边界就是「能否接受丢弃」这条线。规模上限不由专家数决定，而由负载分布稳定性决定：分布漂移后，要么 C 偏小导致 drop rate 升高，要么 C 偏大导致缓冲与显存浪费、专家利用率下降。</p>\n<p>最后一个工程判断落在标定节奏上：C 不是一次性参数，而是随流量分布演化的运维量。把 drop rate 与专家利用率作为在线观测指标，按周或按流量拐点重标定 C，才能让静态形状的收益不被分布漂移吃掉；一旦观测到长尾请求的 drop rate 系统性高于均值，说明批次组成需要重新分组，而不是继续调 C。</p>\n\n<h3 id=\"alg-capacity-factor-routing-sec-6\">六 · 容量因子路由的失效边界：从一次 decode P99 抖动事故说起</h3>\n<p>某在线 MoE 服务在版本上线后的第一个流量高峰出现了一次典型的连锁故障：decode 阶段 P99 时延在数分钟内从稳态水平抬升到数倍，随后触发上游网关超时重试，重试又把 micro-batch 的组成打散，热点专家进一步集中，形成正反馈。根因并不在 kernel 或链路，而在于无容量约束的路由：路由器按 top-k 打分把 token 发往专家，All-to-All 发送缓冲必须按“最坏情况”动态增长，热点专家在某一 micro-batch 内收到的 token 数远超均值，缓冲分配与分组 GEMM 的 M 维在运行时才确定，kernel 需要重编译或走 fallback 路径，长尾时延由此产生。容量因子路由正是针对这一具体病灶：在不改模型权重、不改路由打分函数的前提下，给每个专家一个编译期可确定的 token 上界，把“负载波动”从运行时问题转化为标定问题。</p>\n<p>其机制可以压缩成一条链路：调度器把请求切成固定 token 预算的 micro-batch，路由器对每个 token 计算 top-k 专家打分并按分数排序，每个专家截断到 <span class=\"inline-math\">capacity</span>，溢出 token 标记为 dropped 并直接走残差连接；随后依据 capacity 生成静态 dispatch 矩阵，All-to-All 发送缓冲大小在 kernel launch 之前就已确定；专家侧按固定 M=capacity 的分组 GEMM 计算，tcgen05 的 tile 形状无需运行时重排；combine 阶段按原路由权重加权回填，dropped token 用残差输出进入下一层。容量本身由单一旋钮决定：</p>\n<div class=\"formula\">$$\\text{capacity}=\\left\\lceil \\text{capacity\\_factor}\\times\\frac{\\text{tokens per batch}}{\\text{num\\_experts}} \\right\\rceil,\\quad \\text{drop rate}=\\frac{1}{T}\\sum_{t=1}^{T}\\mathbb{1}\\left[\\text{rank}_e(t)&gt;\\text{capacity}\\right]$$</div>\n<p>它解决的是“可预测性”而非“质量”：All-to-All 缓冲与分组 GEMM 形状静态化，避免了运行时动态分配与 kernel 重编译，decode 阶段 P99 因此可承诺；代价被显式搬到 drop rate 上，材料给出的标定点是 C=1.25 时 drop rate 通常低于 1%。但它不解决专家利用率问题，也不解决负载分布漂移：容量因子按离线负载分布标定，一旦在线 batch 组成变化——例如代码补全流量在夜间占比上升、数学推理请求集中到少数专家——静态 dispatch 矩阵虽然仍可预测，专家利用率却下降，吞吐不达预期；偏小则 drop rate 升高，长尾请求质量骤降，偏大则 All-to-All 缓冲与显存被白白占用。失效条件因此可以列成一张简表。</p>\n<table class=\"mini\"><thead><tr><th>条件</th><th>系统表现</th><th>工程判断</th></tr></thead><tbody><tr><td>流量分布漂移、容量因子未重标定</td><td>drop rate 升高或缓冲浪费</td><td>需按负载分布周期性离线标定，不能一次定死</td></tr><tr><td>代码、数学等长尾请求遇专家偏斜</td><td>drop rate 显著高于均值，残差旁路使输出质量不可控</td><td>这类请求应走独立队列或更高容量因子</td></tr><tr><td>micro-batch 组成剧烈变化</td><td>形状可预测但专家利用率下降</td><td>批调度需与容量标定联动，而非各自独立调参</td></tr></tbody></table>\n<p>与相邻方案的分界同样重要：专家选择路由反转方向使每专家负载恒等于 k、彻底无丢弃，但破坏因果性；无丢弃块稀疏分组 GEMM 用块级 padding 替代 token 丢弃，代价是 padding 带来的无效计算与显存占用。容量因子路由选择的是“以丢弃换静态形状与可预测 P99”，因此它适用于 decode 主导、SLO 以尾时延为硬约束、且负载分布可在离线阶段稳定刻画的服务；不适用于质量不可妥协的长尾生成、负载分布高频漂移或专家数极少导致单专家容量颗粒度过粗的场景。规模上限受负载分布稳定性约束，材料未给出具体专家数上限，工程上应以 drop rate 与专家利用率的联合监控作为扩容前提。</p>\n<h3 id=\"alg-capacity-factor-routing-sec-7\">七 · 请求切分与 token 预算落定</h3>\n<p>容量因子路由的第一步不在路由器，而在调度器。请求进入后被切成固定 token 预算的 micro-batch，这个预算不是随便取的：它同时是 capacity 公式的分子、dispatch 矩阵的行数上界、以及专家侧分组 GEMM 的 M 维来源。设 micro-batch 内 token 数为 T，专家数为 E，容量因子为 C，则每专家容量为</p>\n<div class=\"formula\">$$\\text{capacity}=\\left\\lceil C\\cdot\\frac{T}{E}\\right\\rceil$$</div>\n<p>输入是调度器队列中的请求集合及其长度分布，输出是一个 token 数恰好为 T 的 micro-batch 以及由它推导出的标量 capacity。代价发生在两处：其一，T 越大，capacity 越大，All-to-All 发送缓冲按 E×capacity×hidden 规模线性膨胀，显存占用随之上升；其二，T 越小，capacity 向下取整效应越明显，C=1.25、E 较大时 capacity 可能只比 T/E 多一两个 token，负载均衡的余量被吃掉。工程上 T 的选择要与 KV cache 分页粒度、decode 阶段每步的 batch 组成对齐，否则同一 capacity 在不同 step 上对应的实际 token 数不一致，静态形状失去意义。举例：一个 decode step 聚合了 512 个请求各 1 个 token，T=512，E=64，C=1.25，则 capacity=⌈1.25×8⌉=10，每专家最多收 10 个 token，总槽位 640，冗余 128 个槽位即为负载波动的缓冲。</p>\n\n<h3 id=\"alg-capacity-factor-routing-sec-8\">八 · 路由打分与排序截断</h3>\n<p>路由器对 micro-batch 内每个 token 计算 top-k 专家打分，得到 token→专家的候选映射。这一步的输出不是最终的 dispatch 矩阵，而是一张带分数的候选表。随后按分数排序，对每个专家截断到 capacity：分数高的 token 占据槽位，排名超出 capacity 的 token 被标记为 dropped。判定条件可写成</p>\n<div class=\"formula\">$$\\text{drop rate}=\\frac{1}{T}\\sum_{t=1}^{T}\\mathbb{1}\\left[\\text{rank}_e(t)&gt;\\text{capacity}\\right]$$</div>\n<p>输入是候选表与 capacity，输出是每个 token 的三种归宿之一：进入某专家的槽位、被丢弃走残差、或在 top-k 中部分专家命中部分丢弃。代价在这里首次显性化：排序本身是 O(T·k·log) 量级的操作，在 decode 阶段每步都要做，属于纯延迟开销，且排序的并行度受 token 维度限制，难以完全隐藏。更重要的是语义代价——被截断的 token 不是随机丢的，而是分数排名靠后的，这意味着模型对这批 token 的专家 specialization 判断被否决。长尾请求（代码、数学）在专家偏斜时 drop rate 显著高于均值，因为这些请求的 token 集中命中少数几个专家，排序截断恰好切在它们身上。工程判断：截断应按专家独立进行而非全局统一阈值，否则热点专家的溢出会连带压低冷门专家的利用率。</p>\n\n<h3 id=\"alg-capacity-factor-routing-sec-9\">九 · 静态 dispatch 矩阵生成</h3>\n<p>截断完成后，据 capacity 生成静态 dispatch 矩阵，把每个 token 映射到专家槽位。关键性质是这张矩阵的维度在 kernel launch 前就已确定：行数为 T，列数为 E×capacity，非零元位置由路由结果决定但形状固定。输入是截断后的 token→专家映射，输出是一份可直接喂给 All-to-All 的发送索引与缓冲布局。代价体现在缓冲分配上：发送缓冲大小 = E×capacity×hidden×dtype_bytes，在 NVFP4 权重激活下 hidden 维的字节数被压缩，但 capacity 的膨胀是线性的，C 从 1.0 调到 1.5 意味着缓冲扩大一半。另一个代价是 dispatch 矩阵的构造本身要在 GPU 上完成 scatter，若用原子操作写槽位，热点专家的槽位竞争会引入串行化；实践中多用分段前缀和加稳定排序来避免原子冲突。举例：capacity=10、E=64、hidden=7168、FP8 单字节，则发送缓冲约 64×10×7168≈4.6 MB 每层每 micro-batch，层数叠加后这是显存规划里必须预留的固定项，而非按需增长项。</p>\n\n<h3 id=\"alg-capacity-factor-routing-sec-10\">十 · All-to-All 发送与接收</h3>\n<p>dispatch 矩阵确定后，All-to-All 的发送缓冲大小在 kernel launch 前已知，通信 kernel 无需运行时探测消息大小。输入是本 rank 上按目标专家分组的 token 块，输出是各专家所在 rank 收到的定长槽位数组。这一步的代价是带宽与同步：NVLink 5 上的 All-to-All 延迟由消息大小和 rank 数共同决定，静态缓冲把消息大小从“随批次波动”变成“编译期常量”，从而让通信与计算的重叠调度可以提前编排。代价的另一面是无效流量：capacity 大于实际负载时，槽位里填充的是 padding，这些字节照样过网，浪费带宽。设实际负载为 L_e，则带宽浪费比例近似为 1−ΣL_e/(E·capacity)，C=1.25 时理论浪费上限约 20%，但负载偏斜会把有效浪费推得更高。工程上把 padding 槽位标记为无效并在接收侧跳过 GEMM 行，可省算力但省不了带宽，这是静态形状换来的确定性所付的固定税。tcgen05 的 tile 形状无需运行时重排，正是因为接收侧数组的 M 维恒等于 capacity。</p>\n\n<h3 id=\"alg-capacity-factor-routing-sec-11\">十一 · 分组 GEMM 与 combine 回填</h3>\n<p>专家侧按固定 M=capacity 的分组 GEMM 计算。输入是每个专家收到的 capacity 行激活（含 padding）与该专家的权重，输出是 capacity 行专家输出。M 维固定带来的直接收益是 tcgen05 的 tile 形状、TMEM 分配、以及 2-SM MMA 的配对方式全部可以在编译期定死，kernel 不需要因批次形状变化而重编译或走动态分支。代价是算力利用率：当某专家实际只收到 capacity 的六成 token 时，剩余四成 GEMM 行是 padding，算力空转；在 decode 阶段 GEMM 本就偏 memory-bound，padding 行的权重读取仍会发生，等于用带宽换确定性。combine 阶段按原路由权重加权回填，dropped token 使用残差输出进入下一层。这里有一个容易忽略的细节：残差旁路的数值路径与专家路径不同，dropped token 的梯度语义在推理中无关，但其输出分布与正常 token 有系统性偏差，长尾请求中这种偏差会累积。举例：一层 MoE 中某数学请求的 8 个 token 有 3 个被丢弃，这 3 个 token 的输出等于其残差加注意力输出，未经专家变换，下一层路由器看到的表示已偏离训练分布，后续层的路由决策随之失真。</p>\n\n<h3 id=\"alg-capacity-factor-routing-sec-12\">十二 · 容量因子的标定与漂移代价</h3>\n<p>容量因子是整条链路上唯一的可调旋钮，但它不是在线自适应量。标定流程是离线的：采集目标流量的专家负载分布，取分位数确定 C，使 drop rate 落在可接受区间。材料给出的锚点是 C=1.25 时 drop rate 通常低于 1%，这个数字对应的是负载分布相对平稳的场景。代价在漂移时显现：流量分布变化后，偏小的 C 使 drop rate 升高、长尾请求质量骤降；偏大的 C 使 All-to-All 缓冲与显存浪费，专家利用率下降、吞吐不达预期。失败模式是双向的，且没有在线信号能立刻区分二者——drop rate 是统计量，单步 decode 里看不出质量损失，只有端到端评测才能暴露。工程判断：把 C 与 micro-batch 的 token 预算绑定调参，而不是单独调 C；T 增大时负载相对均值更集中，同样的 C 对应更低的 drop rate，但缓冲膨胀更快。容量因子路由的本质是用一个编译期常量换取 P99 的可预测性，这个常量的有效期等于负载分布的稳定期，超出这个期限，静态形状带来的收益会被质量损失或显存浪费吃掉。</p>\n\n<h3 id=\"alg-capacity-factor-routing-sec-13\">十三 · 容量因子失配时的失效链条与静态形状的隐性账单</h3>\n\n<p>把步骤按 token 流动顺序摊开，每一步的代价并不对称。调度器切 micro-batch 时，token 预算一旦定下，capacity 就被公式 <span class=\"formula\">$$\\text{capacity}=\\left\\lceil C \\cdot \\frac{T}{E} \\right\\rceil$$</span> 锁死，这一步的代价是零——它只是算术。真正的账单出现在路由器之后：排序截断要付出一次 O(T log T) 的排序开销与一次全量打分写回，代价量级在微秒级但不可省略，因为它决定了 dropped 集合。dispatch 矩阵生成是纯 host 侧或轻量 kernel 的索引构造，代价可忽略，但它把「哪些 token 去哪」固化成了编译期常量。All-to-All 发送缓冲在 kernel launch 前按 capacity×E 静态分配，这一步的显存占用是硬性的：C 偏大时缓冲按最坏情况预留，即使实际负载远低于上界也不释放。专家侧固定 M=capacity 的分组 GEMM 是代价主项——tcgen05 tile 形状无需运行时重排，换来的是每个专家无论实际收到多少 token 都按满 capacity 计算，专家利用率低于 1 时算力被空转浪费。combine 阶段按原路由权重加权回填，dropped token 走残差，这一步不增加额外通信量，但残差旁路意味着该 token 在本层的专家变换被整体跳过。\n\n<table class=\"mini\"><thead><tr><th>步骤</th><th>输入</th><th>输出</th><th>主要代价</th></tr></thead><tbody><tr><td>切 micro-batch</td><td>请求流</td><td>固定 token 预算批次</td><td>批大小受 capacity 与显存约束</td></tr><tr><td>路由打分+排序截断</td><td>token 隐状态</td><td>top-k 打分、dropped 标记</td><td>排序开销、打分写回</td></tr><tr><td>静态 dispatch</td><td>capacity、路由结果</td><td>token→专家槽位矩阵</td><td>缓冲按上界预留显存</td></tr><tr><td>分组 GEMM</td><td>固定 M=capacity</td><td>专家输出</td><td>低利用率下算力空转</td></tr><tr><td>combine 回填</td><td>专家输出、原权重</td><td>层输出（含残差旁路）</td><td>dropped token 质量损失</td></tr></tbody></table></p>\n\n<p>失效条件集中在容量因子与真实负载分布的错配上，且错配方向决定失效形态。C 偏小：drop rate 按 <span class=\"formula\">$$\\text{drop rate}=\\frac{1}{T}\\sum_{t=1}^{T}\\mathbb{1}\\left[\\text{rank}_e(t)&gt;\\text{capacity}\\right]$$</span> 升高，长尾请求受害最重——代码与数学类请求的 token 在专家空间上分布偏斜，热点专家集中承接，rank 超过 capacity 的比例显著高于均值，dropped token 走残差旁路后这些请求的输出质量不可控，且不可控程度随批次组成漂移而波动。C 偏大：All-to-All 缓冲与分组 GEMM 的 M 维按放大后的上界静态预留，显存与算力双重浪费，专家利用率下降，吞吐不达预期，而 P99 时延的「可预测」变成「可预测地偏高」。更隐蔽的失效是分布漂移本身：容量因子按离线负载标定，在线 batch 组成变化后，静态 dispatch 矩阵与 GEMM 形状仍然可预测，但可预测性建立在错误的先验上——形状对了，负载错了，系统稳定地跑在低效点上。\n\n工程判断落在标定周期与监控口径上。容量因子是单一旋钮，但它的最优值随流量分布漂移，因此需要把 drop rate 按请求类别（而非全局均值）做在线监控，长尾类别的 drop rate 突破阈值即触发重标定；同时把专家利用率作为并行指标，避免只盯 drop rate 而忽略 C 偏大带来的空转。材料给出的锚点是 C=1.25 时 drop rate 通常低于 1%，这个数字只在标定分布内成立，跨分布直接套用就是把质量风险转嫁给长尾请求。规模上限受负载分布稳定性约束，分布越稳定，静态形状的收益越能兑现；分布抖动剧烈时，丢弃换来的 P99 可预测性会被质量方差抵消，此时应转向块级 padding 的无丢弃分组 GEMM，用块内 padding 替代 token 丢弃，代价是 GEMM 有效算力下降而非质量损失。</p>\n\n<h3 id=\"alg-capacity-factor-routing-sec-14\">十四 · 容量因子失配时的系统账本：从 dispatch 矩阵到残差旁路的代价传导</h3>\n<p>静态 dispatch 矩阵一旦在 kernel launch 前固化，容量因子就不再是运行时可以临时调整的旋钮，而是一个编译期承诺。承诺兑现的前提是 micro-batch 内 top-k 打分的分布与离线标定时一致；一旦流量分布漂移，capacity 与实际每专家 token 数之间的缺口会沿三条路径传导：偏小时，溢出 token 被标记 dropped 并直接走残差连接，All-to-All 发送缓冲虽仍按 capacity 分配、不会膨胀，但残差旁路意味着这些 token 在本层完全绕过专家计算，等效于该层对这一 token 的表示更新被跳过；偏大时，dispatch 矩阵按虚高的 capacity 分配槽位，发送缓冲与分组 GEMM 的 M 维被撑大，显存占用与 All-to-All 通信量同步上升，而实际填充率下降，tcgen05 的 tile 在大量空槽位上做无效 MMA，吞吐不达预期。两种失配都不改变 kernel 形状的可预测性，却把代价从“时延抖动”转移到了“质量损失”或“利用率损失”，这是该方案最本质的权衡位置。</p>\n<p>把失配代价写成可核算的形式，设第 $e$ 个专家在 micro-batch 内实际收到 $n_e$ 个 token，则有效利用率与丢弃率为</p>\n<div class=\"formula\">$$\\text{util}_e=\\frac{\\min(n_e,\\text{capacity})}{\\text{capacity}},\\quad \\text{drop rate}=\\frac{1}{T}\\sum_{t=1}^{T}\\mathbb{1}\\left[\\text{rank}_e(t)&gt;\\text{capacity}\\right]$$</div>\n<p>其中 $\\text{rank}_e(t)$ 是 token $t$ 在其所选专家上的打分排序位次。利用率项直接对应显存与带宽浪费：capacity 偏大时，All-to-All 发送缓冲按 capacity 分配，combine 阶段回填的槽位数也按 capacity 组织，即便多数槽位为空，NVLink 5 上的传输与 TMEM 中的 tile 装载仍按满形状执行。丢弃率项对应质量损失：C=1.25 时 drop rate 通常低于 1%，这是均值口径；代码、数学这类长尾请求在专家偏斜时 drop rate 显著高于均值，dropped token 走残差旁路后，这些请求的输出质量不可控——不是因为丢弃本身随机，而是因为丢弃集中在它们最依赖的少数热点专家上。</p>\n<p>工程上真正需要盯住的边界条件有三个。其一是 micro-batch 的 token 预算与 capacity 的耦合：批大小受 capacity 与显存约束，token 预算切得越细，单批内专家分布越接近均匀，drop rate 越可控，但调度器切分与 kernel launch 的开销占比上升，decode 阶段 P99 的收益被切分开销侵蚀；切得越粗，分布方差越大，长尾请求越容易被整批拖入高 drop rate 区间。其二是离线标定的时效性：容量因子按负载分布标定，在线 batch 组成变化后，静态 dispatch 矩阵与 GEMM 形状虽可预测，但专家利用率下降是渐进的、不会触发任何告警，运维侧只能从吞吐不达预期反推失配。其三是与相邻方案的边界：专家选择路由反转方向使每专家负载恒等于 k、彻底无丢弃但破坏因果性，无丢弃块稀疏分组 GEMM 用块级 padding 替代 token 丢弃——本方案以丢弃换静态形状与可预测 P99，适用规模上限受负载分布稳定性约束，分布越稳定，容量因子越能贴近真实均值，静态化的收益才越充分。</p>\n<h3 id=\"alg-capacity-factor-routing-sec-15\">十五 · 容量公式的逐项解剖与量纲校验</h3>\n<p>核心公式只有一行，但每一项都对应一个可测量的系统量，写错一个量纲就会让整个静态化设计失效：</p>\n<div class=\"formula\">$$\\text{capacity}=\\left\\lceil \\text{capacity\\_factor}\\times\\frac{\\text{tokens per batch}}{\\text{num\\_experts}}\\right\\rceil$$</div>\n<p>分子 tokens per batch 是 micro-batch 内实际参与路由的 token 数，不是请求数，也不是序列长度；分母 num_experts 是全局专家总数，在专家并行下它跨设备分布，因此 capacity 是“每专家在本地接收的 token 上界”，而不是每卡上界——若采用 E 路专家并行、每卡放 E/P 个专家，则每卡本地 token 上界是 capacity × E/P，这个换算必须在 dispatch 矩阵生成时完成，否则 All-to-All 发送缓冲会按错误的粒度分配。capacity_factor 是无量纲标量，理想均匀路由下它等于 1 时 capacity 恰好等于均值；C>1 表示允许热点专家超出均值一定比例，C<1 则是主动压缩。向上取整不是装饰：capacity 必须为整数，且后续分组 GEMM 的 M 维直接取这个整数，任何小数都会让 tcgen05 的 tile 形状在编译期无法确定。</p>\n<p>推导的关键一步在于把“随机负载”替换为“确定性上界”。设第 e 个专家在 batch 内收到的 token 数为 n_e，路由器打分排序后截断，则实际进入专家计算的 token 数为 min(n_e, capacity)。于是溢出量 o_e = max(0, n_e − capacity)，总丢弃率即：</p>\n<div class=\"formula\">$$\\text{drop rate}=\\frac{1}{T}\\sum_{t=1}^{T}\\mathbb{1}\\left[\\text{rank}_e(t)&gt;\\text{capacity}\\right]$$</div>\n<p>这里的 rank_e(t) 是 token t 在专家 e 的打分排序中的位次，指示函数在位次超出 capacity 时取 1。注意求和是对 token 而非对专家，所以 drop rate 是“被丢弃 token 占总 token 的比例”，与按专家求平均的溢出率不是同一个量——前者直接对应质量损失，后者对应显存浪费。工程上必须同时盯这两个数：drop rate 决定输出质量，而 Σ min(n_e, capacity) 与 Σ n_e 的差决定 All-to-All 缓冲的填充率。C=1.25 时 drop rate 通常 <1%，这个锚点的含义是：负载偏斜在 25% 以内的专家全部被容纳，只有超出 1.25 倍均值的极端热点才丢 token，而真实负载的偏斜大多落在这一区间内。</p>\n<p>代价体现在三个方向。延迟侧：capacity 一旦确定，dispatch 矩阵与 GEMM 形状静态化，decode 阶段 P99 可预测，因为最坏情况下的专家计算量被硬性封顶。显存与带宽侧：All-to-All 发送缓冲大小 = capacity × hidden_dim × dtype_bytes × top_k，在 kernel launch 前即可算出并预分配，避免了动态扩容带来的碎片与拷贝。吞吐侧：C 偏大则缓冲膨胀、专家利用率下降；C 偏小则 drop rate 上升。举例：一个 micro-batch 有 8192 个 token、64 个专家、top-2 路由，C=1.25 时 capacity = ceil(1.25 × 8192/64) = 160，每专家固定 M=160 的分组 GEMM，64 个专家共 10240 个槽位，而实际 token 路由次数是 16384，意味着约 6144 个路由槽位被截断或旁路——这个数字直接告诉你缓冲该开多大、GEMM 该切几块。</p>\n\n<h3 id=\"alg-capacity-factor-routing-sec-16\">十六 · 从打分到截断：排序截断的等价形式</h3>\n<p>机制上“按打分排序后截断到 capacity”听起来是 O(n log n) 的排序，但落到 kernel 里必须避免真排序。可实现的等价形式是：对每个专家维护一个容量为 capacity 的最小堆（或阈值寄存器），遍历该专家候选 token 的打分，仅当打分高于当前堆顶时替换。由于 top-k 路由下每个 token 只投给 k 个专家，候选集是稀疏的，逐专家处理的总工作量是 O(T·k·log capacity)，远小于全局排序。更实用的做法是两遍法：第一遍统计每个专家的候选计数 n_e 并与 capacity 比较，第二遍只对 n_e > capacity 的专家做阈值选择——阈值可通过直方图或分位估计快速得到，无需精确排序。</p>\n<p>截断的判定必须与路由权重解耦。token 被截断后不是简单消失，而是标记 dropped 并走残差连接，这意味着 combine 阶段该 token 的输出等于其输入残差加上其余未丢弃专家的加权和。伪代码落到可实现层面大致如下：</p>\n<ul>\n<li>输入：micro-batch 的 token 隐状态 X（T×H）、路由打分 S（T×E）、top-k 索引与权重 W（T×k）。</li>\n<li>步骤 1：对每个专家 e，收集候选 token 集合 cand[e] = {t : e ∈ topk(t)}，计数 n_e = |cand[e]|。</li>\n<li>步骤 2：若 n_e ≤ capacity，全部接纳；否则按 S[t,e] 取前 capacity 个，其余标记 dropped[t] 并置该路由槽位为空。</li>\n<li>步骤 3：按 (e, slot) 二元组生成静态 dispatch 矩阵 D，形状固定为 E×capacity，D[e, s] = token 全局偏移或空标记；D 的大小在编译期确定。</li>\n<li>步骤 4：All-to-All 按 D 打包发送，接收侧按固定 M=capacity 组装分组 GEMM 的 A 矩阵，空槽位填零且不参与 combine。</li>\n<li>步骤 5：combine 阶段对每个 token 按其原路由权重加权求和未丢弃的专家输出；若该 token 的 k 个路由全部被丢弃，输出直接取残差。</li>\n</ul>\n<p>这里有一个容易被忽略的工程细节：步骤 2 的“取前 capacity 个”在不同专家之间是独立的，因此同一个 token 可能在专家 A 被接纳、在专家 B 被丢弃，combine 权重必须按实际接纳情况重新归一化，否则输出幅度会随丢弃率漂移。归一化因子是 Σ_{e∈accepted} W[t,e]，当它为 0 时退化为纯残差。这个归一化在 kernel 里是一次 per-token 的归约，代价可忽略，但漏掉它会让长尾请求的输出分布明显偏移。</p>\n<p>系统代价：两遍法的第一遍需要一次全 batch 的专家计数归约，在 E 较大时是一次 E 长度的原子加，延迟在微秒级；第二遍的阈值选择对热点专家是 O(n_e) 扫描。相比全局排序，这套流程把路由阶段的最坏延迟从 O(T log T) 压到 O(T·k)，在 decode 这种 T 较小的场景下差异不明显，但在分块预填的大 micro-batch 下是实打实的收益。例子：T=8192、k=2、E=64 时，全局排序约需 8192×13 次比较量级，而逐专家计数加阈值选择只需约 16384 次候选遍历加 64 次截断，路由阶段的寄存器压力与分支发散都显著下降。</p>\n\n<h3 id=\"alg-capacity-factor-routing-sec-17\">十七 · 静态 dispatch 矩阵与缓冲上界的推导</h3>\n<p>静态化的真正价值不在 capacity 这个数本身，而在于它把 All-to-All 的发送缓冲从“运行时才知道”变成“编译期就能算”。设 hidden_dim 为 H、dtype 字节数为 b、top_k 为 k，则单卡发送缓冲上界为：</p>\n<div class=\"formula\">$$B_{\\text{send}}=\\text{capacity}\\times\\frac{E}{P}\\times H\\times b\\times k$$</div>\n<p>其中 E/P 是每卡本地专家数。这个式子的推导只需一步：dispatch 矩阵 D 的形状是 E×capacity，每卡负责其中 E/P 行，每行 capacity 个槽位，每个槽位携带一个 H 维、b 字节的向量，且一个 token 最多向 k 个专家发送，故上界即上式。关键在于 B_send 不含任何依赖运行时负载的项——n_e 的波动被 capacity 截断吸收，缓冲大小与真实负载无关。这就是“kernel launch 前确定”的物理含义：NVLink 5 上的传输可以按固定 chunk 切分，NCCL 的 all-to-all 可以预分配 bucket，避免动态 bucket 带来的重排与额外同步。</p>\n<p>接收侧对称地有 B_recv = capacity × (E/P) × H × b × k，但接收缓冲的填充率取决于实际接纳的 token 数，空槽位填零后仍参与 GEMM 的 M 维。这意味着 GEMM 的有效利用率是 Σ min(n_e, capacity) / (E×capacity)，在负载均匀时接近 1/C，在负载偏斜时更低。C=1.25 的选取正是在这个利用率与 drop rate 之间取平衡：C 越大，GEMM 空转越多、显存与带宽浪费越大；C 越小，drop rate 越高、质量损失越明显。</p>\n<p>代价的具体形态：以 H=7168、b=1（FP8）、k=2、E=64、P=8 为例，每卡本地专家 8 个，capacity=160 时 B_send = 160×8×7168×1×2 ≈ 18.3 MB 量级——这是一个可以常驻预分配的固定值，而不是随 batch 波动的动态峰值。若没有 capacity 约束，热点专家可能收到数倍于均值的 token，缓冲峰值不可预测，decode 阶段的 P99 会被缓冲扩容与拷贝拖长。反过来，若 C 取到 2.0，capacity 翻倍到 320，缓冲与 GEMM 的 M 维同步翻倍，显存占用与计算量都翻倍而 drop rate 收益甚微，这是典型的“旋钮拧过头”。</p>\n\n<h3 id=\"alg-capacity-factor-routing-sec-18\">十八 · 固定 M 分组 GEMM 与 tcgen05 tile 的对齐</h3>\n<p>capacity 的第二个用途是给分组 GEMM 一个固定的 M。专家侧计算的是 E/P 个独立的小 GEMM，每个的 M 都是 capacity、N 与 K 是专家权重的形状。tcgen05 的 MMA 指令要求 tile 形状在指令发射时确定，若 M 随负载波动，要么在运行时重排 tile、要么退化为 padding 到最大可能 M，两者都带来额外开销。固定 M=capacity 后，tile 划分在编译期完成：capacity 若为 160，按 64 或 128 的 tile 切分需要处理尾块，因此实践中常把 capacity 向上对齐到 tile 边界（如 192 或 256），这一步对齐会让实际容量略大于公式值，但换来 tile 形状的整齐。</p>\n<p>推导上的关键一步是把“每专家一个 GEMM”看成“一个 batched GEMM，batch=E/P、M=capacity”。分组 GEMM 的调度器按 (专家, tile) 二维展开，tile 数 = (E/P) × ceil(capacity/M_tile)，这个数在编译期就是常量，可以直接用于 SM 占用率估算与 CTA 发射规划。TMEM 的分配同样按固定 tile 数进行，不会出现运行时 TMEM 不足导致的回退。代价是：当实际接纳 token 远少于 capacity 时，空槽位仍占用 MMA 的 M 维，算力被浪费；这部分浪费与 C 成正比，是容量因子最直接的吞吐代价。</p>\n<p>例子：capacity=192、M_tile=64 时每专家 3 个 tile，E/P=8 时共 24 个 tile，若 SM 数为 148，则每个 SM 分不到一个 tile，分组 GEMM 的并行度受限于 tile 总数而非 SM 数——这说明 capacity 过小会让 GEMM 欠并行，容量因子不能只按 drop rate 调，还要看 tile 总数是否够铺满 SM。反过来 capacity 过大则 tile 数膨胀、每 tile 的有效行数下降，同样浪费。这个“tile 总数与 SM 数的匹配”是容量因子标定时必须一起看的第二个约束，与 drop rate 构成一对张力。</p>\n\n<h3 id=\"alg-capacity-factor-routing-sec-19\">十九 · 丢弃率与容量因子的标定方程</h3>\n<p>容量因子不能拍脑袋，标定的本质是解一个关于负载分布的方程。设专家负载 n_e 的分布已知（离线从真实流量统计），则 drop rate 是 C 的函数：</p>\n<div class=\"formula\">$$\\text{drop}(C)=\\frac{1}{T}\\sum_{e}\\mathbb{E}\\left[\\max(0,\\,n_e-\\text{capacity}(C))\\right]$$</div>\n<p>标定就是找最小的 C 使得 drop(C) 低于质量容忍阈值（材料给出的锚点是 C=1.25 时 drop rate <1%）。这一步的推导依赖负载分布的形状而非具体数字：若分布接近均匀，C 略大于 1 即可；若存在少数极端热点专家（长尾请求、代码与数学类输入在专家偏斜时尤其明显），分布的尾部决定了 C 的下界。工程上可用的做法是：采集若干 micro-batch 的 n_e 直方图，对候选 C 网格逐点计算 drop(C) 与 GEMM 利用率，选满足 drop 约束的最小 C，再检查 tile 总数是否够铺满 SM。</p>\n<p>失败模式的机理在此清晰：流量分布漂移后，离线标定的 C 与在线负载失配。C 偏小则 drop rate 升高，长尾请求质量骤降且不可控——因为 dropped token 走残差旁路，模型对这些 token 的“思考”被跳过，输出质量随丢弃位置随机波动；C 偏大则 All-to-All 缓冲与显存浪费，专家利用率下降、吞吐不达预期。两种失配都不是崩溃式的，而是缓慢劣化，因此需要在线监控 drop rate 与 GEMM 填充率两个指标，任一越界就触发 C 的重标定。代价是重标定本身需要一次离线统计窗口，窗口内的流量仍在用旧 C 服务，这段过渡期的质量与吞吐都不在承诺范围内。</p>\n<p>一个具体的工程判断：长尾请求（代码、数学）的 drop rate 显著高于均值，若 SLO 对这些请求有单独的质量承诺，就不能用全局平均 drop rate 做标定，而应按请求类别分层统计，对长尾类别取更保守的 C 或对其路由做额外保护（例如提高该类请求的 top-k 权重或限制其进入热点专家）。这一步把容量因子从单一全局旋钮变成按类别分层的旋钮组，代价是标定复杂度上升，但换来了长尾请求质量的可控性。</p>\n\n<h3 id=\"alg-capacity-factor-routing-sec-20\">二十 · 可实现性检查：从公式到 kernel 参数</h3>\n<p>把公式落到 kernel 参数上，需要确认三件事在编译期可定：dispatch 矩阵形状、GEMM 的 M、缓冲字节数。三者都由 capacity 唯一决定，而 capacity 由 C、T、E 决定，其中 T 是 micro-batch 的 token 预算——这意味着调度器切 micro-batch 时必须按固定 token 预算切，不能按请求边界切，否则 T 波动会让 capacity 波动、静态化失效。这是“固定 token 预算”这一步骤的真正原因，而非调度偏好。</p>\n<p>伪代码层面的可实现性还要求截断与 dispatch 生成在同一 kernel 或紧邻的两个 kernel 内完成，避免中间结果落回全局显存。可行的融合是：路由 kernel 输出每个 token 的 top-k 索引与权重，紧接着的截断 kernel 按专家维度做阈值选择并直接写出 dispatch 矩阵的槽位索引，两个 kernel 之间只传递打分与索引，不传递隐状态。隐状态的搬运发生在 All-to-All 打包阶段，按 dispatch 矩阵的槽位顺序 gather，这一步的访存模式是规则的，因为槽位顺序静态。</p>\n<p>系统代价的最后一项是功耗与带宽：静态缓冲意味着 NVLink 5 上的传输量在 launch 前已知，可以按固定速率调度，避免动态峰值带来的功耗尖峰；但空槽位填零仍占用带宽，填充率越低，单位有效 token 的传输能耗越高。工程判断是：容量因子的选取应使 GEMM 填充率维持在可接受的下界之上，drop rate 与填充率两个指标同时约束 C，而不是只看 drop rate。当负载分布稳定、长尾请求占比低时，C 可以贴近 1；当长尾占比高且质量承诺严格时，C 需要上抬并配合分层保护，此时静态化的收益让位于质量，但 P99 的可预测性仍然保留——这正是本算法以丢弃换静态形状的边界所在。</p>\n<h3 id=\"alg-capacity-factor-routing-sec-21\">二十一 · 负载配方的三个自由度：token 预算、micro-batch 组成与容量因子</h3>\n<p>容量因子路由不是“设一个 C 就完事”的开关，它把推理负载切成三块互相牵制的参数：micro-batch 的 token 预算 <em>T</em>、批内请求的组成（长度分布与领域分布）、以及容量因子 C。三者共同决定每专家上界 <em>capacity</em> 与丢弃率。工程上真正要标定的不是 C 本身，而是“在给定 SLO 下，什么样的请求组合能被塞进同一个 micro-batch 而不让 C 失效”。</p>\n<p>调度器按固定 token 预算切 micro-batch，这一刀切法直接决定负载配方的形状。若预算按“最长请求”对齐，短请求会被 padding 稀释，实际参与路由的有效 token 变少，capacity 相对偏大，All-to-All 缓冲按上界分配却装不满，带宽利用率下降；若预算按“平均长度”切，长请求被拆到多个 micro-batch，同一请求的 token 分散在不同批次里路由，专家负载在批次间抖动，C 的离线标定值失去意义。因此 token 预算必须与长度分布的分位数绑定：以 P95 长度作为切分参考，让绝大多数请求落在单个 micro-batch 内，只有极长请求才跨批。</p>\n<p>批内组成是第二个自由度。容量公式 <em>capacity</em> = ⌈C · T / E⌉ 里 T 是批内 token 总数、E 是专家数，公式本身对“这些 token 来自哪些请求”一无所知。但路由打分是内容相关的：一批全是通用对话时专家打分接近均匀，C=1.25 足以让丢弃率压在 1% 以下；一批混入代码或数学请求时，这些 token 的 top-k 打分高度集中在少数“擅长符号推理”的专家上，同样的 C 会让这些专家溢出。负载配方的核心判断是：<strong>不要把领域分布差异大的请求混进同一个 micro-batch</strong>，否则 C 只能按最坏偏斜标定，等于给均匀负载白白放大缓冲。</p>\n<div class=\"formula\">$$\\text{capacity}=\\left\\lceil C\\cdot\\frac{T}{E}\\right\\rceil,\\quad \\text{drop rate}=\\frac{1}{T}\\sum_{t=1}^{T}\\mathbb{1}\\left[\\text{rank}_e(t)&gt;\\text{capacity}\\right]$$</div>\n<p>代价是显性的：T 越大，capacity 越大，All-to-All 发送缓冲与专家侧分组 GEMM 的 M 维同步膨胀，显存与带宽按 O(T·C/E) 线性上涨；T 越小，批内统计越不稳定，专家负载方差相对均值变大，同样的 C 对应更高的丢弃率。decode 阶段尤其敏感——每步只产生一个 token，micro-batch 的 token 数等于并发序列数，并发低时 T 小、capacity 小、丢弃率对 C 的微小偏差极度敏感。</p>\n\n<h3 id=\"alg-capacity-factor-routing-sec-22\">二十二 · 适合的请求形态：短到中等长度、领域均匀、并发稳定</h3>\n<p>这套机制最适合的形态是：长度分布集中在中短区间（单请求 token 数落在同一数量级）、领域分布均匀（通用对话、摘要、检索增强问答这类路由打分分散的任务）、并发量稳定且可预测（在线服务有平稳的 QPS 基线）。在这种形态下，批内 token 的 top-k 打分近似独立同分布，专家负载的波动被大数定律压平，C=1.25 就能把丢弃率控制在 1% 以内，同时 All-to-All 缓冲与 tcgen05 分组 GEMM 的 tile 形状在编译期固定，decode P99 时延可预测。</p>\n<p>具体例子：一个检索增强问答服务，输入是拼接后的文档片段加问题，输出是短答案，长度分布在几百 token 量级且方差小；请求按到达顺序切成固定预算的 micro-batch，每批 token 数稳定，路由打分分散在多数专家上。此时容量因子按离线统计的专家负载分位数标定，运行期几乎不需要调整，静态 dispatch 矩阵每批形状一致，kernel launch 前缓冲大小确定，专家侧按固定 M=capacity 计算，无需运行时重排。</p>\n<p>并发与批大小的匹配是形态适配的另一半。decode 阶段的并发序列数就是每步的 token 数，并发越高 T 越大、capacity 越大、单次 GEMM 的 M 维越大，tcgen05 的利用率越好；但并发高到一定程度，KV cache 与专家权重共存的显存压力上升（这部分见分页 KV 与专家权重共存显存一节），批大小被迫收缩，T 回落，capacity 随之缩小，丢弃率上升。负载配方要在这条曲线上找拐点：让并发稳定在“显存允许的最大 T”附近，而不是盲目追高并发。</p>\n<ul>\n<li>适合：中短长度、领域均匀、并发平稳的在线服务；离线批量推理中长度可预分桶的场景。</li>\n<li>不适合：长度重尾（少量超长请求主导 token 总量）、领域高度混合、并发剧烈波动的场景。</li>\n<li>判断依据：离线统计批内专家负载的变异系数，变异系数小则 C 可压低，变异系数大则 C 必须放大或改分批策略。</li>\n</ul>\n\n<h3 id=\"alg-capacity-factor-routing-sec-23\">二十三 · 长度分布不对时：重尾请求把 capacity 拖向两端</h3>\n<p>长度分布重尾是这套机制最直接的敌人。假设 token 预算按 P95 长度切分，少量超长请求（长文档、多轮对话历史）会占满整个 micro-batch 的预算，批内 token 几乎全部来自同一请求。单请求内部的 token 在语义上高度相关，路由打分容易集中到少数专家——一篇代码文件的 token 反复命中同一批专家，capacity 按均匀假设算出的上界被瞬间击穿，丢弃率飙升。</p>\n<p>反过来，如果为了容纳超长请求而放大 token 预算，capacity 随 T 线性放大，All-to-All 缓冲按最坏情况分配，短请求批次里大量槽位空置，显存与带宽被浪费，吞吐不达预期。这就是长度分布不对时的两端拉扯：<strong>预算小了丢 token，预算大了浪费缓冲</strong>，而 C 这个单一旋钮无法同时解决两个方向的问题。</p>\n<p>工程上的处理不是调 C，而是改分批：按长度分桶，把同量级的请求放进同一 micro-batch，让批内 token 数的方差收敛；超长请求单独成批并允许更低的 C（更高的丢弃率）或走残差旁路比例更高的配置。代价是分桶带来调度复杂度与批内等待——为了凑齐同桶请求，调度器要维护多个待批队列，短请求可能等待长请求凑批，尾延迟上升。这是一个显式的权衡：用调度侧的排队延迟换路由侧的容量可预测性。</p>\n\n<h3 id=\"alg-capacity-factor-routing-sec-24\">二十四 · 领域分布不对时：长尾任务的专家偏斜击穿 C=1.25</h3>\n<p>领域分布不对比长度分布不对更隐蔽，因为它在 token 计数上看不出来。一批 token 总数正常、长度均匀，但内容全是代码或数学推导时，路由打分向少数专家集中，这些专家的 rank 迅速超过 capacity。材料明确指出：代码、数学等长尾请求在专家偏斜时丢弃率显著高于均值，被丢弃的 token 走残差旁路，导致这些请求的输出质量不可控。</p>\n<p>为什么不可控？残差旁路意味着该 token 跳过专家计算、直接以残差流进入下一层，等价于这一层对这个 token 做了恒等映射。对通用对话，单层跳过的影响被后续层稀释；对代码这种对局部语法结构敏感的 token，跳过一层专家计算可能直接改变标识符、运算符或缩进相关的表示，错误会沿层传播。丢弃率在均值上看着不到 1%，但在代码请求内部可能集中在关键 token 上，质量损失不是线性的。</p>\n<p>负载配方对此的应对是把领域维度纳入分批：按请求的领域标签（或轻量分类器打标）分池，代码与数学请求单独成批，对这些批次单独标定更高的 C 或接受更高的丢弃率并显式记录。代价是领域分类本身的延迟与误分类风险，以及多池并行带来的显存碎片——每个池都要预留按各自 capacity 计算的 All-to-All 缓冲，总缓冲不再是一个静态上界而是多个上界之和。工程判断是：只有当长尾领域的流量占比高到值得单独开池时才这么做，否则宁可让这些请求走非容量约束的路径（例如专家选择路由或块稀疏分组 GEMM，见对应条目），而不是硬塞进容量因子框架。</p>\n\n<h3 id=\"alg-capacity-factor-routing-sec-25\">二十五 · 并发与批大小漂移：静态形状可预测，利用率却掉了</h3>\n<p>容量因子路由的卖点是形状静态化：dispatch 矩阵按 capacity 生成，All-to-All 缓冲在 kernel launch 前确定，tcgen05 tile 形状无需运行时重排，decode P99 可预测。但这个“静态”是对单次 launch 而言的，跨批次看，批大小随流量漂移，capacity 跟着 T 变，静态形状每批都在换一套参数。流量下降时 T 变小、capacity 变小，专家侧 GEMM 的 M 维变小，tcgen05 的 tile 利用率下降；流量上升时 T 变大、capacity 变大，缓冲膨胀但专家利用率未必同步上升——因为专家负载的偏斜程度也随批组成变化。</p>\n<p>失败模式很具体：容量因子按离线负载标定，在线 batch 组成变化后，静态 dispatch 矩阵与 GEMM 形状虽然每批可预测，但专家利用率下降、吞吐不达预期。这不是正确性问题，是经济性问题——你为可预测性付了固定的缓冲与显存代价，却在漂移后的负载上收不回成本。漂移的典型来源是时段性流量（白天通用请求多、夜间批量代码任务多）和上游路由策略变化（检索系统改了召回条数，输入长度整体偏移）。</p>\n<p>应对手段是周期性重标定而非在线自适应：按固定窗口统计批内专家负载分布，重算 C 的分位数，重编静态 dispatch 模板。重标定本身有代价——切换窗口时在途请求可能落在旧模板上，需要版本化 dispatch 矩阵并允许新旧模板短暂共存。工程上更稳的做法是把 C 设为分段常数（例如按流量档位给几组 C），用调度器的档位信号切换，而不是让 C 连续跟踪负载，避免每批重编译 kernel 抵消静态化收益。</p>\n<table class=\"mini\"><thead><tr><th>负载特征</th><th>配方选择</th><th>主要代价</th></tr></thead><tbody><tr><td>中短长度、领域均匀、并发平稳</td><td>单池、C=1.25、按 P95 长度切预算</td><td>缓冲按上界预留，低峰期利用率下降</td></tr><tr><td>长度重尾</td><td>按长度分桶、超长请求单独成批</td><td>凑批等待带来尾延迟</td></tr><tr><td>领域高度混合</td><td>按领域分池、长尾池单独标定 C</td><td>多池缓冲叠加、显存碎片</td></tr><tr><td>并发剧烈漂移</td><td>分段常数 C、周期性重标定</td><td>模板切换期的在途请求风险</td></tr></tbody></table>\n<p>最终落到一个工程判断上：容量因子路由的负载配方本质是“用分批策略把批内专家负载的方差压到 C 能覆盖的范围”，C 只是这个方差的上界标记。长度分桶压的是 token 数方差，领域分池压的是打分集中度方差，分段常数 C 压的是跨时段漂移方差。三者都不做而只调 C，等于让一个标量去吸收三个维度的不确定性，结果必然是偏小丢质量、偏大浪费缓冲，且两者随流量漂移交替出现。</p>\n\n<h3 id=\"alg-capacity-factor-routing-sec-26\">二十六 · 负载配方错配时，静态形状反而成为负债</h3>\n<p>容量因子路由的收益全部建立在“负载分布可预测”这一前提上。它把每个专家的 token 数压到 <span class=\"formula\">$$\\text{capacity}=\\left\\lceil C \\cdot T/E \\right\\rceil$$</span> 的上界，从而让 All-to-All 发送缓冲和分组 GEMM 的 M 维在 kernel launch 前就固定下来。但这也意味着，调度器切出的 micro-batch 组成必须与离线标定 C 时所用的负载配方同构：请求类型集中、长度分布收敛、并发稳定。一旦 micro-batch 内混入大量长尾请求（代码补全、数学推导、多轮工具调用），路由打分向少数专家集中，drop rate 就会从均值以下迅速抬升。此时被丢弃的 token 走残差旁路，输出质量不可控，而 P99 时延却因为形状静态化依然“好看”——可预测性掩盖了质量塌陷。</p>\n<p>失效条件可以写成一个判据：设 micro-batch 内实际每专家 token 数为 <span class=\"formula\">$$n_e$$</span>，则溢出量为 <span class=\"formula\">$$\\sum_e \\max(0, n_e - \\text{capacity})$$</span>。当该值相对总 token 数的占比超过标定时的 drop rate 预算（材料给出 C=1.25 时通常 &lt;1%），说明负载配方已经漂移。偏小的 C 让长尾请求质量骤降；偏大的 C 则让 All-to-All 缓冲与专家侧激活显存按最坏情况预留，decode 阶段每 token 的搬运字节数和 GEMM 的无效 padding 同步上升，吞吐不达预期。两种错配的代价不对称：前者是质量事故，后者是显存与带宽浪费，工程上通常宁可先偏大再逐步收紧。</p>\n<p>具体例子：一个以短对话为主的在线服务按 C=1.25 标定，drop rate 稳定在 1% 以下；当同一批 GPU 被复用去承接代码生成流量时，micro-batch 内序列变长、专家偏斜加剧，溢出 token 集中在少数热点专家上，这些请求的残差旁路比例显著高于对话流量。系统侧的表现是 All-to-All 缓冲不再膨胀（形状静态），但专家利用率下降、有效吞吐被 padding 吃掉。判断边界的方法不是看平均 drop rate，而是按请求类别分别统计 <span class=\"formula\">$$\\frac{1}{T}\\sum_{t=1}^{T}\\mathbb{1}[\\text{rank}_e(t)&gt;\\text{capacity}]$$</span>，把长尾类别的 drop rate 作为容量因子重新标定的触发信号；若某类别持续越界，说明该负载不适合这套静态容量方案，应改用块级 padding 的无丢弃分组 GEMM，或把长尾请求隔离到独立副本上单独配方。</p>\n<h3 id=\"alg-capacity-factor-routing-sec-27\">二十七 · 硬件档位与并行拓扑的耦合约束</h3>\n<p>容量因子路由的部署配方不是先选机器再调参，而是被一条硬约束反向锁死：dispatch 矩阵与分组 GEMM 的 M 维必须在 kernel launch 前静态确定。这意味着并行拓扑一旦确定，每张卡上每个专家实例的 capacity 就是一个编译期常量，硬件档位决定了这个常量能取多大而不撑爆显存与 All-to-All 缓冲。</p>\n<p>拓扑选择上，专家并行度 E_parallel 与 capacity 的乘积直接决定单卡 All-to-All 发送缓冲的字节数：</p>\n<div class=\"formula\">$$B_{\\text{send}} = \\text{capacity} \\times d_{\\text{model}} \\times b_{\\text{elem}} \\times k$$</div>\n<p>其中 k 为 top-k 路由数，b_elem 为元素字节宽度。在 NVLink 5 域内做专家并行时，这个缓冲驻留在发送端 SMEM 与远端 HBM 的暂存区，capacity 翻倍即缓冲翻倍。工程判断是：把 E_parallel 取到单机 NVLink 域能容纳的最大值（GB200 NVL72 机柜内可跨 72 个 GPU 做专家分片），使每卡专家数下降、单专家 capacity 上升，从而在相同 token 预算下降低 drop rate——因为 capacity 公式的分母 num_experts 是全局专家数，而每卡实际承载的专家子集越小，热点专家越容易在卡内被摊平。</p>\n<p>具体例子：一个 64 专家的 MoE 层，若 E_parallel=8，每卡 8 个专家，micro-batch 4096 token、C=1.25，则 capacity=⌈1.25×4096/64⌉=80，每卡发送缓冲按 80×d_model×2×k 计；若把 E_parallel 提到 16，capacity 不变但每卡专家数减半，单卡 GEMM 的 M 维仍为 80，而热点专家的排队长度在卡内被更多 SM 分摊，tcgen05 的 tile 形状保持固定，无需运行时重排。代价是跨机通信跳数增加，All-to-All 的尾延迟随跳数线性上升，因此拓扑档位的选择本质是在 drop rate 与通信长尾之间取点。</p>\n\n<h3 id=\"alg-capacity-factor-routing-sec-28\">二十八 · 量化方案与 capacity 的数值耦合</h3>\n<p>量化方案不是独立选项，它通过元素字节宽度 b_elem 直接进入发送缓冲公式，并通过 GEMM 的 tile 对齐约束反过来限制 capacity 的取值粒度。NVFP4 权重激活微缩放把 b_elem 压到 0.5 字节量级，发送缓冲随之减半，同等显存下 capacity 可翻倍，drop rate 下降；但 tcgen05 分组 GEMM 对 M 维有 tile 对齐要求，capacity 必须是 tile 行数的整数倍，否则静态形状失效、退化为 padding。</p>\n<p>因此配方里 capacity 的取值要向上取整到 GEMM tile 行数的倍数，而不是直接用公式的 ceil 结果。伪代码思路：</p>\n<ul>\n<li>raw = ceil(C × tokens_per_microbatch / num_experts)</li>\n<li>capacity = ceil(raw / tile_M) × tile_M</li>\n<li>若 capacity × E_parallel × b_elem × k 超过单卡发送缓冲预算，则回退：降 C 或升 E_parallel</li>\n</ul>\n<p>量化精度档位与 KV 策略在此处交汇：KV cache 占用的是与专家权重共存的显存池（该共存机制在其他部分展开），KV 分页块越大，留给专家权重与发送缓冲的余量越小。工程上把 KV 块大小固定为与 capacity 同量级的对齐值，使显存分配器在一次静态规划中同时容纳 KV 页表与 dispatch 缓冲，避免运行时碎片化导致的 capacity 缩水。具体例子：同一 MoE 层在 FP8 下 b_elem=1，capacity=80 时单卡发送缓冲为 80×d_model×1×k 字节；切到 NVFP4 后 b_elem≈0.5，同容量缓冲减半，多出的显存正好容纳更大的 KV 分页块，decode 阶段 P99 因 KV 命中率提升而改善，而 drop rate 因 capacity 可上调而下降——两个收益来自同一次量化决策。</p>\n\n<h3 id=\"alg-capacity-factor-routing-sec-29\">二十九 · KV 策略与调度参数的联动</h3>\n<p>调度参数里真正与容量因子路由耦合的只有三个：micro-batch 的 token 预算、连续批处理的准入窗口、以及 decode 阶段的 piggyback 比例。token 预算直接进 capacity 公式的分子，预算越大 capacity 越大、drop rate 越低，但单次 All-to-All 的数据量与 GEMM 的 M 维同步膨胀，decode 的 P99 随 batch 线性恶化。准入窗口决定新请求能否插入当前 micro-batch，窗口越宽、batch 组成越动态，离线标定的容量因子越容易失配。</p>\n<p>KV 策略在此的作用是给 token 预算设上限：分页 KV 的显存占用随并发序列数增长，而专家权重与发送缓冲是静态预留，两者争抢同一 HBM 池。配方做法是把 KV 预算设为显存总额减去静态预留（专家权重 + capacity 决定的发送缓冲 + 激活峰值）后的余量，再由 KV 预算反推最大并发序列数，进而约束 micro-batch 的 token 预算。这形成一个闭环：</p>\n<div class=\"formula\">$$\\text{tokens per batch} \\le \\frac{\\text{HBM} - W_{\\text{expert}} - B_{\\text{send}}(C)}{s_{\\text{kv}} \\cdot L}$$</div>\n<p>其中 s_kv 为每 token 每层的 KV 字节数，L 为层数。调度器据此设定准入窗口，使 batch 组成变化被限制在容量因子可容忍的范围内。具体例子：当流量从短对话漂移到长文档摘要时，平均序列长度上升、KV 占用上升，token 预算被迫下调，capacity 随之下降，原本 C=1.25 下 <1% 的 drop rate 会向上升——这正是失败模式中“流量分布漂移后容量因子失配”的触发路径，配方必须在准入窗口层面做序列长度分桶，把长序列请求隔离到独立 micro-batch，避免其 KV 占用挤压短请求的 token 预算。</p>\n\n<h3 id=\"alg-capacity-factor-routing-sec-30\">三十 · 可复现配置思路：从 SLO 反推旋钮</h3>\n<p>可复现的配方不是给一组魔数，而是给一条从 SLO 反推的决策链，每一步都有明确的约束来源。顺序如下：</p>\n<ul>\n<li>定 SLO：decode 阶段 P99 时延目标，以及可接受的质量损失上限（以 drop rate 表达）。</li>\n<li>定拓扑：在 NVLink 域内取最大 E_parallel，使每卡专家子集最小化，降低卡内热点排队。</li>\n<li>定量化：按显存预算选 NVFP4 或 FP8，b_elem 决定发送缓冲与 capacity 的可达上限。</li>\n<li>定 capacity：由 C 与 token 预算算出 raw，向上对齐到 tile_M，再校验发送缓冲不超预算。</li>\n<li>定 KV：静态预留扣除后反推最大并发序列数，据此设准入窗口与序列长度分桶。</li>\n<li>离线标定 C：在目标流量分布上扫 C，取满足 drop rate 上限的最小值，留出漂移余量。</li>\n</ul>\n<p>这条链的关键在于每一步都把上一部的输出当作硬约束而非建议值。capacity 对齐 tile_M 后可能比 raw 大出半个 tile，这部分多余容量在低负载时浪费显存、在高负载时正好吸收波动，是配方里唯一允许的“故意浪费”。具体例子：若 tile_M=64、raw=80，则 capacity 对齐到 128，多出的 48 个槽位在均值负载下空转，但当某专家瞬时偏斜时这 48 个槽位就是缓冲，drop rate 从对齐前的尖峰被削平；代价是发送缓冲按 128 而非 80 预留，显存占用上升 60%，必须在 KV 预算里扣回来。</p>\n\n<h3 id=\"alg-capacity-factor-routing-sec-31\">三十一 · 漂移监测与旋钮的在线调整边界</h3>\n<p>容量因子是离线标定的静态量，但流量分布会漂移，配方必须定义在线可调与不可调的边界。不可调的是 dispatch 矩阵形状与 GEMM 的 M 维——它们绑定在已编译的 kernel 上，改动即触发重编译，decode 长尾立刻失控。可调的是准入窗口、序列长度分桶比例、以及 micro-batch 的 token 预算在容量上限内的收缩。</p>\n<p>监测指标应直接对准失败模式：按请求类别（代码、数学、对话）分别统计 drop rate，因为长尾请求在专家偏斜时 drop rate 显著高于均值，全局均值会掩盖这一偏斜。当某类别的 drop rate 越过阈值，配方动作不是调 C（那会破坏静态形状），而是把该类请求路由到独立 micro-batch 并降低其 token 预算占比，用更小的 batch 换取更均匀的专家分布。工程判断是：容量因子路由的稳定性来自形状静态化，任何试图在线改 C 的操作都会把可预测的 P99 换成不可预测的 kernel 重编译停顿，因此 C 的调整只能发生在版本发布边界，在线只动调度侧的批组成。</p>\n<p>具体机制上，调度器维护每个专家类别的滑动窗口 drop 计数，与 capacity 的静态值比对，超出即触发分桶重排；这一步不改变任何 kernel 形状，只改变 token 进入哪个 micro-batch，因此对 P99 的影响是准入延迟而非计算延迟。代价是分桶后小 batch 的 GEMM 利用率下降、吞吐不达预期，这正是失败模式中“专家利用率下降”的来源，配方需在 SLO 与吞吐之间显式记账，而不是让漂移悄悄侵蚀质量。</p>\n\n\n<h3 id=\"alg-capacity-factor-routing-sec-32\">三十二 · 容量因子标定之后：配方失效的三种边界与可复现的验证路径</h3>\n<p>把部署配方写成一份可复现的清单，关键不在于列出硬件型号，而在于明确每个旋钮在什么条件下会失配。容量因子 C 的标定本质上是离线分布与在线分布之间的一次赌注：离线采样得到每专家 token 数的经验分布，取分位数反解出 C，再验证 drop rate 是否落在可接受区间。公式上，给定 micro-batch 的 token 预算 T、专家数 E，每专家平均负载为 T/E，容量为 <span class=\"formula\">$$\\text{capacity}=\\left\\lceil C\\cdot\\frac{T}{E}\\right\\rceil$$</span>，而实际 drop rate 是排序截断后溢出 token 占比 <span class=\"formula\">$$\\text{drop rate}=\\frac{1}{T}\\sum_{t=1}^{T}\\mathbb{1}\\left[\\text{rank}_e(t)&gt;\\text{capacity}\\right]$$</span>。注意这两个量对 C 的敏感度并不对称：C 从 1.0 抬到 1.25，capacity 线性增长，但 drop rate 的下降取决于分布尾部厚度，长尾请求（代码、数学）的专家打分集中度更高，尾部更厚，同样的 C 增量换来的 drop rate 改善远小于均值流量。这就是配方必须按请求类型分层标定、而不能用全局平均分布一锤定音的原因。</p>\n<p>第一个失效边界是流量分布漂移。静态 dispatch 矩阵与分组 GEMM 形状在编译期确定，换来的是 decode P99 可预测，但代价是系统对分布变化没有自适应能力。当在线 batch 的专家命中分布偏离离线标定分布时，C 偏小则 drop rate 抬升、长尾请求质量骤降；C 偏大则 All-to-All 发送缓冲按 capacity 分配、显存与带宽被闲置槽位占用，专家利用率下降、吞吐不达预期。工程上应把 C 的标定结果与监控指标绑定：以 dropped token 比例和每专家槽位填充率作为双阈值，填充率长期低于某水平说明 C 过大，drop rate 越过 SLO 容忍线说明 C 过小，两者同时恶化则说明分布已漂移、需要重标定而非调 C。这一步不能在线上自动搜索 C，因为改变 C 会改变 kernel launch 的缓冲尺寸与 GEMM 形状，触发重编译，反而破坏 P99 的稳定性。</p>\n<p>第二个失效边界是长尾请求的质量不可控。dropped token 走残差旁路进入下一层，等价于该 token 在本层未经过专家变换，对短提示、高频模板类请求影响有限，但对代码与数学这类依赖精确中间表示的请求，残差旁路会累积成输出错误。配方上应把丢弃策略与请求分类绑定：对长尾类别单独使用更高的 C 或改用块级 padding 的无丢弃分组 GEMM（见相邻算法条目），代价是该类请求的 GEMM 形状不再与主路径共享静态模板，需要独立的 kernel 变体与缓冲预算。系统代价体现在显存上：两套形状意味着两份 All-to-All 缓冲上限，容量规划时不能只按主路径的 C 计算。</p>\n<p>第三个边界是 micro-batch 切分与 capacity 的耦合。请求按固定 token 预算切成 micro-batch，批大小同时受 capacity 与显存约束；T 越小，T/E 越小，capacity 的整数取整误差占比越大，C=1.25 在专家数较多时可能只多出个位数槽位，drop rate 的方差反而上升。可复现的配置思路是固定 T 与 E 后先扫 C 的候选点，记录每个点的 drop rate 与槽位填充率，选取 drop rate 满足 SLO 且填充率不低于阈值的最小 C；材料给出的锚点是 C=1.25 时 drop rate 通常低于 1%，但这一数字只在标定分布内成立，跨分布复用必须重新验证。下表给出配方要素与失效信号的对应关系，供容量规划时逐项核对。</p>\n<table class=\"mini\"><thead><tr><th>配方要素</th><th>静态化收益</th><th>失配信号</th><th>系统代价</th></tr></thead><tbody><tr><td>容量因子 C</td><td>缓冲与 GEMM 形状编译期确定</td><td>drop rate 越线或填充率过低</td><td>显存闲置或质量损失</td></tr><tr><td>micro-batch 预算 T</td><td>dispatch 矩阵规模可预测</td><td>取整误差致 drop 方差上升</td><td>P99 抖动</td></tr><tr><td>丢弃旁路策略</td><td>combine 回填路径固定</td><td>长尾类别输出错误累积</td><td>需独立 kernel 变体与缓冲</td></tr></tbody></table>\n<p>把这三条边界写进配方文档，比给出任何硬件档位都更有工程价值：C 是唯一旋钮，但它只在标定分布内有效；静态形状换来的 P99 可预测性，以放弃在线自适应为代价；长尾请求的丢弃必须单独治理，否则残差旁路会把质量损失藏进输出里而不触发任何时延告警。</p>\n<h3 id=\"alg-capacity-factor-routing-sec-33\">三十三 · 静态形状换来的吞吐：从 kernel launch 到 SM 占用</h3>\n<p>容量因子路由真正的吞吐收益不在“丢了多少 token”，而在“编译期就知道要发多少字节、要开多大的 GEMM”。一旦 capacity 确定，dispatch 矩阵的稀疏模式虽然仍是数据相关的，但每个专家的接收槽位数是常量 M=capacity，于是 All-to-All 的发送缓冲可以按 <span>num_experts × capacity × hidden_bytes</span> 一次性预留，分组 GEMM 的每个分组 M 也是常量。对 Blackwell 的 tcgen05 路径而言，这意味着 tile 形状（M 方向的 64/128 分块、N 方向的 swizzle）在 kernel launch 前即可选定，CTA pair 的 2-SM MMA 配对关系不需要在运行时按实际 token 数重排。代价体现在利用率上：当实际到达某专家的 token 数远小于 capacity 时，GEMM 仍在算 padding 出来的空行，SM 的 tensor core 在做无效乘加。设专家 e 的实际接收量为 <span>n_e ≤ capacity</span>，则该专家的算力浪费比为</p>\n<div class=\"formula\">$$\\text{waste}_e = 1 - \\frac{n_e}{\\text{capacity}},\\qquad \\text{aggregate waste} = \\frac{1}{E}\\sum_{e=1}^{E}\\left(1-\\frac{n_e}{\\text{capacity}}\\right)$$</div>\n<p>这条式子说明容量因子是双向代价：C 偏大，waste 上升，tensor core 空转、功耗不降；C 偏小，drop rate 上升，质量受损。工程判断是看“有效吞吐”而非“峰值吞吐”——把 waste 计入后，C=1.25 在负载相对均衡的批次上通常仍优于动态形状方案，因为后者要付出 kernel 重编译与动态分配的启动开销；但在专家偏斜严重的批次上，waste 可以吞掉静态化带来的全部收益。</p>\n\n<h3 id=\"alg-capacity-factor-routing-sec-34\">三十四 · 显存与带宽：缓冲静态化的真实账</h3>\n<p>All-to-All 缓冲静态化把“峰值不确定”变成“峰值可预留”，这在显存规划上是决定性的。动态方案必须按最坏情况预留，否则热点专家溢出会触发重分配甚至 OOM；静态方案按 capacity 预留，缓冲大小是 <span>E × capacity × d</span>（d 为单 token 负载字节数），与 NVFP4/FP8 的量化位宽直接挂钩——量化把 d 压小，等于把同一块显存能容纳的 capacity 抬高，这是容量因子与量化策略必须联合标定的原因。带宽侧的账更细：dispatch 阶段写入缓冲、专家侧读出、combine 阶段再写回，每个未被丢弃的 token 在 NVLink 5 上至少走两趟；被丢弃的 token 只走残差旁路，省掉两趟跨卡流量，但也意味着这部分计算被彻底跳过。于是有效跨卡字节数为</p>\n<div class=\"formula\">$$\\text{bytes}_{\\text{comm}} \\approx 2 \\cdot (T - T_{\\text{drop}}) \\cdot d \\cdot k,\\qquad T_{\\text{drop}} = T \\cdot \\text{drop rate}$$</div>\n<p>注意这里 drop 反而降低了通信量，所以“丢弃”在带宽维度上是省钱的，代价全部记在质量账上。真正吃带宽的是 combine 阶段：即使 token 未被丢弃，加权回填也要把专家输出按原路由权重聚合，top-k>1 时同一 token 的输出要从 k 个专家位置拉回，这部分流量与 capacity 无关、只与 T 和 k 有关，是容量因子无法优化的固定开销。规模上去后，先崩的往往不是这条固定开销，而是缓冲预留与 KV cache 争抢同一块 HBM——容量因子调大直接压缩 KV 的可用页数，进而压低可并发的 decode 序列数。</p>\n\n<h3 id=\"alg-capacity-factor-routing-sec-35\">三十五 · 通信拓扑：All-to-All 的尾延迟从哪来</h3>\n<p>在 NVL72 这种机架级域内，All-to-All 的稳态带宽不是瓶颈，尾延迟才是。静态 dispatch 矩阵让每个 rank 的发送量可预知，于是 NCCL 的 all-to-all 可以走固定 chunk 切分，避免动态方案里“某个 rank 突然多发几倍”造成的链路争用。但静态化并不消除不均衡：capacity 是上界，实际每个 rank 发往各专家的 token 数仍取决于路由结果，若某专家的接收量贴近 capacity 而相邻专家空转，链路上的 chunk 分布依旧偏斜，尾延迟由最忙的那条链路决定。分离式专家并行部署下这一点被放大——预填节点与解码节点的专家分布不同，dispatch 要跨两个资源池，静态矩阵只保证“大小确定”，不保证“路径均衡”。工程上的做法是把 capacity 与专家放置联合考虑：把高负载专家打散到不同 NVLink 域，让单条链路的期望负载接近 <span>T·k/E</span>，再用 capacity 截断吸收方差。功耗维度上，静态 GEMM 的 padding 空转是纯浪费——tensor core 在算零，功耗照付，这也是为什么大规模部署里 C 的标定要跟着电价与 SLO 一起算，而不是只看 drop rate。</p>\n\n<h3 id=\"alg-capacity-factor-routing-sec-36\">三十六 · 规模上去以后哪里先崩：三个次序</h3>\n<p>把规模推上去，崩溃次序有明确的工程规律。第一崩的是尾延迟的可预测性：micro-batch 内 token 数 T 变大后，路由打分的方差随之变大，capacity 按均值乘以 C 得到的上界对长尾批次的覆盖变差，P99 上出现尖刺——不是平均变慢，而是少数批次里 drop rate 骤升、残差旁路集中触发，输出质量与延迟同时劣化。第二崩的是显存：capacity 随 T 线性增长，缓冲预留与 KV 页、专家权重三者在 HBM 上直接竞争，T 翻倍时缓冲翻倍，KV 可容纳的并发序列数被挤压，decode 吞吐反而下降。第三崩的才是通信带宽：在 NVL72 域内带宽余量通常足够，跨域或跨池的分离式部署才会先撞带宽墙。这个次序说明容量因子路由的规模上限由“负载分布稳定性”而非“链路带宽”决定——分布漂移让离线标定的 C 失配，偏小则长尾质量崩，偏大则显存与算力浪费同时发生。</p>\n<table class=\"mini\"><thead><tr><th>规模维度</th><th>先撞的墙</th><th>表现</th><th>缓解方向</th></tr></thead><tbody><tr><td>T 增大</td><td>尾延迟方差</td><td>P99 尖刺、批次级 drop 集中</td><td>按分位数而非均值标定 C</td></tr><tr><td>E 增大</td><td>显存缓冲</td><td>E×capacity×d 挤压 KV 页</td><td>量化压 d、分池放置专家</td></tr><tr><td>跨池部署</td><td>链路均衡</td><td>最忙链路决定尾延迟</td><td>专家打散到不同 NVLink 域</td></tr></tbody></table>\n\n<h3 id=\"alg-capacity-factor-routing-sec-37\">三十七 · 吞吐与 SLO 的联合标定：把 C 当容量规划变量</h3>\n<p>容量因子不能只当算法超参，它是容量规划里的一个自由度。给定 SLO 目标（decode P99）与可接受的质量损失（drop rate 上界），标定问题是在离线负载分布上求一个 C，使得缓冲预留、GEMM padding 浪费、drop 质量损失三者的联合代价最小。伪代码思路是：对每个候选 C，用历史路由分布重放 micro-batch，统计 <span>drop rate(C)</span> 与 <span>waste(C)</span>，再折算成有效吞吐 <span>TPS_eff = TPS_peak × (1 − waste) × (1 − drop_penalty)</span>，取满足 P99 约束的最大值。这里的 drop_penalty 不是线性项——长尾请求（代码、数学）在专家偏斜时 drop rate 显著高于均值，残差旁路让这些请求的输出质量不可控，所以标定必须按请求类别分层，而不是用全局平均 drop rate 蒙混。流量分布漂移后，离线 C 失配，要么浪费显存要么丢 token 增多，工程上需要在线监控每专家接收量的分位数，触发 C 的重标定或专家重放置，而不是等 P99 报警再回头查。</p>\n<p>最终落点是一个具体机制：把 capacity 的标定从“离线一次性”改成“按 micro-batch 分位数滚动更新”，让静态 dispatch 矩阵的尺寸在若干个调度周期内保持常量、跨周期缓慢跟随分布漂移。这样既保留了 tcgen05 分组 GEMM 形状静态化带来的 kernel 免重编译与 P99 可预测，又避免了固定 C 在分布漂移下的系统性失配——代价是标定逻辑本身要占用调度器的一小段关键路径，且滚动窗口的长度直接决定了对突发偏斜的响应速度。</p>\n\n<h3 id=\"alg-capacity-factor-routing-sec-38\">三十八 · 静态形状的账单：缓冲、带宽与尾延迟在何处先失衡</h3>\n<p>容量因子路由把不确定性从运行时挪到了编译期，代价随之从“动态分配”变成“固定预留”。最直接的账单落在 All-to-All 发送缓冲上：每个 micro-batch 的 dispatch 矩阵形状由 capacity 决定，缓冲按 num_experts × capacity × hidden_bytes 预留，与真实负载无关。设每 token 隐藏维字节数为 h、top-k 为 k，则单层单次 All-to-All 的发送侧缓冲下界为</p>\n<div class=\"formula\">$$\\text{buf}\\approx k\\cdot N_e\\cdot \\text{capacity}\\cdot h$$</div>\n<p>其中 N_e 为参与该并行组的专家数。capacity 由容量因子线性放大，缓冲与显存占用同步线性放大；C 从 1.0 抬到 1.25，缓冲即多出四分之一，而这段显存在整个 decode 期间常驻、不可被 KV cache 借用。规模上去后第一个崩的往往不是算力而是显存预算：KV cache 被挤压，批大小被迫下调，吞吐反而随 C 增大而下降——容量因子在这里不是免费的旋钮，而是显存与丢弃率之间的兑换率。</p>\n<p>第二个先崩的是带宽与通信。静态缓冲让 NCCL/NIXL 的集合通信可以预分配、免去运行时握手，但发送量并不因静态化而减少：被截断的 token 不再发送，可未被截断的热点专家仍要把 capacity 个槽位填满，槽位里既有真实 token 也有为对齐而留的空洞。有效带宽利用率因此写成</p>\n<div class=\"formula\">$$\\eta=\\frac{\\sum_e \\min(n_e,\\text{capacity})}{N_e\\cdot\\text{capacity}}$$</div>\n<p>当负载偏斜（少数专家 n_e 逼近 capacity、多数远低于 capacity）时 η 显著下滑，All-to-All 传的是“形状”而非“信息”。在 NVL72 这类以 NVLink 5 域内高带宽、域间靠 InfiniBand 的拓扑上，域内 All-to-All 尚可被带宽吸收，跨域那一段的固定缓冲会被放大成尾延迟：decode 阶段每层都要走一次 dispatch/combine，P99 由最慢的那次集合通信决定，而静态形状只保证“不变”，不保证“快”。</p>\n<p>功耗与尾延迟的耦合出现在分组 GEMM 侧。专家侧按固定 M=capacity 计算，tcgen05 的 tile 形状无需运行时重排，这是本方案最硬的收益；但固定 M 意味着即使某专家只收到少量 token，GEMM 仍按 capacity 的 tile 数发射，SM 占用与功耗按预留而非按有效负载计。规模扩大后，专家数增多、每专家 capacity 变小，tile 利用率进一步稀释，单位 token 的能耗上升。真正先崩的次序因此可判断为：显存预留 → 跨域 All-to-All 尾延迟 → 固定 M 的能效。失效条件也很清楚：流量分布漂移使离线标定的 C 失配，偏小则长尾请求（代码、数学）在专家偏斜时 drop rate 显著高于均值、残差旁路让输出质量不可控，偏大则缓冲与显存浪费、专家利用率下降、吞吐不达预期；材料给出的 C=1.25、drop rate<1% 只在标定分布内成立，越过分布稳定性这条边界，静态形状带来的可预测性会被质量与能效的双重损失抵消。</p>\n\n<h3 id=\"alg-capacity-factor-routing-sec-39\">三十九 · 静态容量在规模放大后的先崩点：缓冲、利用率与长尾</h3>\n<p>容量因子路由把不确定性从运行时挪到了编译期：dispatch 矩阵与分组 GEMM 的 M 维在 kernel launch 前已固定为 capacity，All-to-All 发送缓冲按 capacity×num_experts 预留，tcgen05 的 tile 形状无需运行时重排。代价是这套静态化假设只在“每专家 token 数 ≤ capacity”时成立。规模上去后第一个崩的不是算力，而是缓冲与显存：capacity 一旦按偏斜负载标定得偏大，每层 All-to-All 缓冲随专家数线性膨胀，micro-batch 的批大小被显存反向压缩，吞吐反而下降；偏小则 drop rate 沿公式 $\\text{drop rate}=\\frac{1}{T}\\sum_{t=1}^{T}\\mathbb{1}[\\text{rank}_e(t)&gt;\\text{capacity}]$ 迅速抬升。真正的临界点是负载分布方差：capacity 是均值乘以 capacity_factor，而热点专家的瞬时 token 数由批次组成决定，batch 越大方差越小、静态上界越稳，batch 越小偏斜越尖锐。</p>\n<p>第二个崩点是通信与尾延迟的耦合。All-to-All 缓冲静态化换来了 P99 可预测，但前提是各 rank 的发送量均衡；一旦某些 rank 承载的热点专家被截断、另一些 rank 的专家槽位空置，NVLink 5 上的 All-to-All 就从“等量交换”退化为“部分 rank 空转等最慢 rank”，尾延迟由最忙 rank 的 capacity 决定而非均值。此时容量因子偏大带来的不是质量收益，而是空槽位占用的带宽与显存；偏小则 dropped token 走残差旁路，combine 阶段加权回填的 token 数减少，专家侧 GEMM 的 M=capacity 固定但有效行稀疏，tcgen05 的利用率被浪费在 padding 行上。</p>\n<p>第三个崩点最隐蔽：容量因子按离线负载分布标定，C=1.25 时 drop rate 通常 &lt;1% 是均值口径。代码、数学这类长尾请求在专家偏斜时 drop rate 显著高于均值，dropped token 走残差旁路使这些请求的输出质量不可控——不是均匀退化，而是按请求类型选择性退化。流量分布漂移后，静态 dispatch 矩阵虽仍可预测，但专家利用率下降、吞吐不达预期，运维只能在“浪费显存”与“丢 token 增多”之间二选一。规模上限因此不由专家数决定，而由负载分布的稳定性决定：分布越稳，capacity 越紧、缓冲越小、P99 越硬；分布漂移越快，离线标定的容量因子越早失配。</p>\n<table class=\"mini\"><thead><tr><th>规模放大后的失效点</th><th>直接代价</th><th>触发条件</th></tr></thead><tbody><tr><td>All-to-All 缓冲膨胀</td><td>显存占用、批大小压缩</td><td>capacity_factor 偏大</td></tr><tr><td>rank 间发送量失衡</td><td>尾延迟由最忙 rank 决定</td><td>专家偏斜 + 截断</td></tr><tr><td>长尾请求质量退化</td><td>drop rate 高于均值</td><td>代码/数学请求集中</td></tr></tbody></table>\n<h3 id=\"alg-capacity-factor-routing-sec-40\">四十 · 精度漂移：丢弃不是随机噪声，而是有偏采样</h3>\n<p>容量因子路由的精度问题与量化误差不是同一类。NVFP4/FP8 的误差是数值层面的、逐元素近似无偏的；丢弃的误差是结构层面的、按专家热度有偏的。被丢的 token 不是随机抽样，而是恰好落在打分排名超出 capacity 的那一段——也就是路由器最\"犹豫\"的那批 token。它们走残差旁路，等价于该层对这批 token 退化为恒等映射，信息未经专家变换直接进入下一层。单层看影响有限，但 MoE 层通常连续堆叠，若同一语义方向的 token 在多层的路由打分都偏低，残差旁路会沿深度累积，形成\"某些 token 从未被任何专家处理过\"的路径。</p>\n<p>诊断这类问题的关键指标不是全局 drop rate，而是按请求类型分桶的 drop rate 与按层统计的 drop rate 方差。全局 drop rate 在 C=1.25 时通常低于 1%，但这个均值会掩盖长尾：代码与数学请求在专家偏斜时 drop rate 显著高于均值。工程上应把 drop rate 做成带标签的直方图——按 prompt 类别、按 token 位置（prefill 还是 decode）、按层号三维切分。若某一层的 drop rate 相对其他层出现稳定偏移，说明该层路由塌缩到少数专家，容量因子对该层偏小。</p>\n<div class=\"formula\">$$\\text{drop rate}=\\frac{1}{T}\\sum_{t=1}^{T}\\mathbb{1}\\left[\\text{rank}_e(t)&gt;\\text{capacity}\\right]$$</div>\n<p>另一个隐蔽的精度失败模式是 combine 阶段的权重归一化。被丢 token 用残差输出，未被丢 token 按原路由权重加权回填；若 top-k 中有部分专家被截断，剩余专家的权重之和不再为 1，而实现上若不做重归一化，输出幅度会系统性偏小。这不是数值 bug，而是路由语义与容量截断之间的语义缝隙。排查方式是拿同一批 token 跑 C 很大（近似无丢弃）与 C=1.25 两个配置，比较逐层激活的范数分布：若某层范数均值出现稳定下移，基本可定位到权重未重归一化或残差旁路比例过高。</p>\n\n<h3 id=\"alg-capacity-factor-routing-sec-41\">四十一 · OOM 与缓冲膨胀：静态形状不等于静态显存</h3>\n<p>容量因子路由的核心承诺是 All-to-All 发送缓冲与分组 GEMM 形状在 kernel launch 前静态确定。但\"静态\"只保证形状可预测，不保证显存占用可预测。发送缓冲按 capacity × hidden × dtype 分配，capacity 随 micro-batch 的 token 预算线性增长；一旦调度器为了提高吞吐放大 micro-batch，capacity 随之抬升，缓冲与专家侧激活的峰值显存同步抬升。OOM 往往不在稳态出现，而在批组成突变的瞬间：一个超长 prompt 被切进 micro-batch，token 预算被撑满，capacity 按公式向上取整跳变，缓冲分配跨过一个显存页边界。</p>\n<p>诊断 OOM 要区分三类来源：其一是 capacity 跳变导致的缓冲超额分配，特征是 OOM 发生在 batch 组成变化后的第一个 micro-batch；其二是分页 KV 与专家权重共存下的碎片化，特征是稳态运行一段时间后可用大块显存持续下降；其三是 combine 阶段的临时缓冲与下一层 prefill 激活叠加。第一类靠限制单 micro-batch 的 token 预算上限解决，把 capacity 的取值域钉死在一组离散档位上，避免连续跳变；第二类要靠显存池的块大小与 KV 页大小对齐，这在分页 KV 那一节已展开，此处只作为交叉约束提示。</p>\n<p>一个具体的工程判断：把 capacity 从\"每 micro-batch 现算\"改为\"按档位查表\"。调度器维护一组预设的 token 预算档位，每个档位对应一个预先标定的 capacity 与缓冲大小，micro-batch 只能落在档位上。代价是批组成灵活性下降、短请求可能被凑进更大的档位造成算力浪费；收益是显存峰值可离线核算，OOM 从运行时故障降级为容量规划问题。</p>\n\n<h3 id=\"alg-capacity-factor-routing-sec-42\">四十二 · 批抖动与路由不均：吞吐不达预期的两个来源</h3>\n<p>批抖动指相邻 micro-batch 的 token 数与专家分布剧烈变化，导致分组 GEMM 的有效利用率波动。容量因子路由把 GEMM 形状固定为 M=capacity，但实际填入的 token 数可能远小于 capacity——当某专家的实际负载低于容量上限时，那部分 tile 是 padding，tcgen05 的 MMA 仍在跑。于是出现一种反直觉现象：drop rate 很低、显存也够，但吞吐上不去。原因是容量因子偏大，capacity 远超实际负载，padding 比例高，专家侧算力被空转消耗。</p>\n<p>诊断批抖动要看两个量的比值：实际每专家 token 数与 capacity 的比值（填充率），以及相邻 micro-batch 之间该比值的方差。填充率长期低于某个阈值说明容量因子偏大；方差大说明批组成不稳定，调度器切分策略需要引入 token 预算的平滑。路由不均则是另一回事：某些专家在所有 micro-batch 上都接近满容量，另一些长期半空。前者触发丢弃，后者制造 padding，两者同时存在时全局 drop rate 与填充率会互相掩盖。</p>\n<table class=\"mini\"><thead><tr><th>现象</th><th>指向</th><th>处置</th></tr></thead><tbody><tr><td>drop rate 升高但填充率也高</td><td>容量因子偏小，热点专家溢出</td><td>上调 C，或对热点专家单独放宽</td></tr><tr><td>drop rate 低但填充率低</td><td>容量因子偏大，padding 空转</td><td>下调 C，收紧 token 预算档位</td></tr><tr><td>填充率方差大</td><td>批组成抖动</td><td>调度器引入预算平滑与档位约束</td></tr><tr><td>单层 drop rate 稳定偏移</td><td>该层路由塌缩</td><td>按层标定容量，而非全局单一 C</td></tr></tbody></table>\n<p>代价落在吞吐与功耗上：padding 空转意味着每 token 的能耗上升，在 GB200 NVL72 这种整机柜功耗预算受限的部署里，空转的 tile 直接吃掉本可用于更多并发请求的功率余量。因此填充率不应只作为性能指标，也应进入功耗侧的容量规划。</p>\n\n<h3 id=\"alg-capacity-factor-routing-sec-43\">四十三 · 尾延迟尖刺：P99 可预测的前提被打破时</h3>\n<p>容量因子路由的设计目标是 decode 阶段 P99 可预测，因为 All-to-All 缓冲与 GEMM 形状静态化，没有运行时动态分配与 kernel 重编译。但 P99 尖刺仍会出现，来源不在稳态路径，而在三个边界：micro-batch 切换档位的瞬间、All-to-All 与计算重叠失败的时刻、以及 dropped token 残差旁路引发的下游层负载再分布。</p>\n<p>第一个边界是档位切换：调度器从低档位跳到高档位，capacity 跳变，缓冲重新分配，即便形状静态，分配动作本身仍在关键路径上。第二个边界是重叠失败：分离式部署下预填与解码的 piggyback 依赖通信与计算的重叠，一旦 NCCL 集合通信与分组 GEMM 的流同步被打断，尾请求会排队等一个完整的 All-to-All 往返。第三个边界最隐蔽：被丢 token 走残差进入下一层，下一层的路由分布因此改变，原本均衡的专家负载出现新的偏斜，尾请求在后续层被二次惩罚。</p>\n<p>监控尾延迟要把 P99 拆成按层、按阶段的分解，而不是只看端到端。具体做法是在每个 MoE 层的 dispatch 前、GEMM 后、combine 后各打一个时间戳，形成层内三段延迟；再按 micro-batch 档位分组统计。若尖刺集中在档位切换的 micro-batch 上，说明缓冲分配在关键路径；若集中在 combine 后，说明残差旁路的负载再分布是主因。回滚策略相应地分两级：档位切换引发的尖刺靠冻结档位、退回上一档位解决；残差旁路引发的尖刺靠临时上调 C 并观察下一层 drop rate 是否收敛来解决。</p>\n\n<h3 id=\"alg-capacity-factor-routing-sec-44\">四十四 · 监控面与回滚：把单一旋钮变成可观测闭环</h3>\n<p>容量因子是单一可调旋钮，但单一旋钮要可运维，必须配一套能定位失配方向的监控面。最小监控集包含四个量：全局 drop rate、按请求类别的 drop rate、专家填充率及其方差、以及层内三段延迟的 P99。这四个量足以区分前四节列出的失败模式：精度漂移看分类 drop rate，OOM 看填充率与缓冲峰值，批抖动看填充率方差，尾延迟看三段延迟分解。</p>\n<p>回滚不是把 C 调回旧值那么简单。流量分布漂移后，旧的 C 对应的旧 dispatch 矩阵与旧 GEMM 形状已经与当前负载不匹配，直接回滚会同时引入丢弃升高与填充率下降。工程上应把回滚定义为\"回到上一组已验证的档位表\"，而不是\"回到上一个 C 值\"——档位表包含 token 预算、capacity、缓冲大小三者的绑定关系，回滚时三者一起切换，避免形状与缓冲错配。回滚触发条件建议用双阈值：分类 drop rate 超过标定上限，且填充率方差同时超过阈值，两者同现才触发，避免单一指标抖动造成频繁回滚。</p>\n<p>一个具体的诊断顺序：先看分类 drop rate 是否偏离，若偏离则查该类别请求的专家分布是否集中在少数专家；再看填充率，若填充率低而 drop rate 高，说明容量因子在全局层面失配而非局部塌缩；最后看层内三段延迟，定位尖刺发生在 dispatch、GEMM 还是 combine。这个顺序把\"质量下降\"与\"性能下降\"分开处理，避免用上调 C 去掩盖路由塌缩，也避免用下调 C 去掩盖缓冲分配问题。回滚动作本身要记录档位表版本与触发指标快照，否则下一次漂移时无法判断是回滚失效还是标定过期。</p>\n<p>最终落在工程判断上：容量因子路由的稳定性不取决于 C 取多少，而取决于档位表是否与当前流量分布同版本。把档位表当作配置资产来版本化管理，让 drop rate 与填充率成为发布门禁的一部分，比在故障后调参更能守住 decode P99 的可预测性。</p>\n\n<h3 id=\"alg-capacity-factor-routing-sec-45\">四十五 · 容量因子失配后的四类现场故障与回滚路径</h3>\n<p>容量因子一旦与在线负载分布脱钩，故障不会以单一形式出现，而是沿四条链路各自显形。其一，路由不均：热点专家在某个 micro-batch 内被截断，drop rate 抬升，而冷专家槽位空转，静态 dispatch 矩阵虽然形状合法，但专家利用率塌陷，吞吐不达预期。其二，批抖动：micro-batch 的 token 预算固定，但请求长度分布变化会让有效 token 数在批间跳动，capacity 与实际需求错位，表现为同一容量因子下 drop rate 逐批漂移。其三，尾延迟尖刺：All-to-All 缓冲虽在 kernel launch 前确定，但 combine 阶段回填的残差旁路 token 会拉长关键路径，P99 尖刺往往先于均值恶化出现。其四，OOM 与精度问题：容量因子偏大使每专家槽位预留过多，All-to-All 发送缓冲与分组 GEMM 的 M=capacity 同步膨胀，显存被静态占满；而 dropped token 走残差连接，长尾请求（代码、数学）在专家偏斜时输出质量不可控，这类精度退化不会触发任何显存或时延告警。</p>\n<p>诊断的核心是把 drop rate 从聚合指标拆到请求维度。聚合 drop rate 用 <span class=\"formula\">$$\\text{drop rate}=\\frac{1}{T}\\sum_{t=1}^{T}\\mathbb{1}\\left[\\text{rank}_e(t)&gt;\\text{capacity}\\right]$$</span> 度量，但 C=1.25 时 drop rate 通常 &lt;1% 的均值会掩盖长尾请求的集中丢弃。工程上应同时记录每请求的 dropped token 占比与其路由熵，把 drop rate 高于均值数倍的请求单独打标，作为精度回滚的触发条件；再以专家维度的 rank 分布直方图判断是全局容量不足还是局部偏斜。批抖动则用相邻 micro-batch 的 capacity 利用率方差监控，方差持续抬升说明 token 预算与请求长度分布已不匹配。</p>\n<p>回滚不是单一动作，而要按故障类型分层。路由不均与批抖动优先调容量因子：上调缓解丢弃但显存与缓冲同步膨胀，下调省显存但 drop rate 升高，因此回滚阈值应绑定 SLO 的 P99 而非均值。尾延迟尖刺先查 combine 阶段残差旁路的占比，若尖刺与 dropped token 比例同向，说明容量因子偏小而非 kernel 问题。精度问题最隐蔽，回滚路径是临时把长尾请求路由到无丢弃块稀疏分组 GEMM 或专家选择路由反转的旁路通道，以吞吐换质量，待离线重新标定容量因子后再切回。OOM 则直接下调容量因子并重编译静态形状，代价是 drop rate 上升，需与质量告警联动。</p>\n<table class=\"mini\"><thead><tr><th>故障</th><th>首要观测量</th><th>回滚动作</th><th>系统代价</th></tr></thead><tbody><tr><td>路由不均</td><td>专家 rank 直方图</td><td>调容量因子</td><td>显存或 drop rate 反向恶化</td></tr><tr><td>批抖动</td><td>capacity 利用率方差</td><td>重切 token 预算</td><td>吞吐下降</td></tr><tr><td>尾延迟尖刺</td><td>残差旁路占比</td><td>上调容量因子</td><td>缓冲膨胀</td></tr><tr><td>精度退化</td><td>每请求 drop 占比</td><td>切无丢弃旁路</td><td>吞吐换质量</td></tr></tbody></table>\n<p>监控的落点是编译期静态形状与运行时丢弃计数的对齐：静态 dispatch 矩阵与 tcgen05 tile 形状在 launch 前已定，任何运行时重排都意味着容量因子失配已越过边界。因此告警应挂在 drop rate 的请求分位数与专家利用率下限上，而非仅看聚合均值；回滚则以容量因子为唯一旋钮，配合长尾请求的旁路开关，把质量损失限制在可观测、可回退的范围内。</p>\n<h3 id=\"alg-capacity-factor-routing-sec-46\">四十六 · 同族算法选型的第一性判据</h3>\n<p>容量因子路由不是孤立存在的，它和专家选择路由、无丢弃块稀疏分组 GEMM 共享同一个目标：让 MoE 推理的专家负载可预测。三者的分歧点在于“可预测性从哪来”。容量因子路由从<strong>截断</strong>来——把每专家 token 数压到 <span class=\"formula\">$$\\text{capacity}=\\left\\lceil C \\cdot \\frac{T}{E} \\right\\rceil$$</span> 的上界，用丢弃换静态形状；专家选择路由从<strong>反转</strong>来——让专家选 token，每专家负载恒等于 k，彻底无丢弃但破坏因果性；块稀疏分组 GEMM 从<strong>padding</strong>来——块级补齐到固定 tile，不丢 token 但放大计算量。选型时先问三个问题：能否接受 token 丢弃？因果性是否可破？padding 带来的算力浪费是否在预算内？三个答案的组合直接锁定算法族。</p>\n<p>工程上更实用的判据是“形状确定时机”。容量因子路由的 dispatch 矩阵与 GEMM 的 M=capacity 在 kernel launch 前静态确定，tcgen05 tile 形状无需运行时重排，这是它相对另外两者的核心优势；专家选择路由虽然负载恒定，但需要跨 token 的全局排序与因果性妥协，在自回归 decode 中代价高；块稀疏分组 GEMM 的 padding 让 M 随块对齐膨胀，算力利用率下降但无需任何丢弃策略。三者的代价分别落在质量、因果性、算力上，选型即是在这三者间做显式取舍。</p>\n\n<h3 id=\"alg-capacity-factor-routing-sec-47\">四十七 · 决策表：按负载形态与 SLO 落位</h3>\n<p>把适用条件压缩成一张可查的表，比记三条定性描述更可靠。下表以“负载偏斜程度”“decode P99 敏感度”“质量容忍度”三个维度给出落位建议，其中偏斜程度指 batch 内 top-1 专家占比相对均匀分布的偏离。</p>\n<table class=\"mini\"><thead><tr><th>条件</th><th>容量因子路由</th><th>专家选择路由</th><th>块稀疏分组 GEMM</th></tr></thead><tbody>\n<tr><td>负载中度偏斜、decode P99 敏感</td><td>首选，C 取 1.25 量级</td><td>因果性代价高，慎用</td><td>padding 放大算力，次选</td></tr>\n<tr><td>负载强偏斜、长尾请求占比高</td><td>drop rate 显著升高，需调大 C</td><td>负载恒定，但排序开销大</td><td>块对齐后仍溢出，需配合丢弃</td></tr>\n<tr><td>质量零容忍（如数学、代码）</td><td>不适用，残差旁路不可控</td><td>无丢弃，但破坏因果性</td><td>首选，用算力换质量</td></tr>\n<tr><td>预填充阶段、token 预算固定</td><td>静态形状收益最大</td><td>全局排序成本可摊薄</td><td>padding 在长序列下占比低</td></tr>\n<tr><td>流量分布漂移频繁</td><td>需在线重标定 C，否则失配</td><td>负载恒定，抗漂移</td><td>块对齐策略需随分布调整</td></tr>\n</tbody></table>\n<p>表中最容易误判的是第二行：强偏斜并不自动意味着该换算法，而是意味着容量因子路由的 C 需要上调，代价是 All-to-All 缓冲与显存按 C 线性放大。若 C 上调后显存预算被击穿，才应考虑块稀疏分组 GEMM 的 padding 路线。反过来，质量零容忍场景下容量因子路由直接出局，因为 dropped token 走残差旁路，长尾请求的输出质量不可控，这不是调 C 能解决的。</p>\n\n<h3 id=\"alg-capacity-factor-routing-sec-48\">四十八 · 与专家选择路由的边界：因果性与排序成本</h3>\n<p>专家选择路由把路由方向反过来，每专家负载恒等于 k，从数学上消除了丢弃。它的代价有两处：一是破坏因果性——token 的未来信息参与专家分配，在自回归 decode 中每个新 token 都要触发全局重排；二是排序成本随 batch 增长，decode 阶段 batch 内 token 数不大时排序尚可摊薄，但一旦进入长上下文预填充，全局排序的通信与同步开销会吃掉静态形状带来的收益。容量因子路由恰恰相反：它保留 token 选专家的因果性，用截断把不确定性挡在 GEMM 之前。</p>\n<p>一个具体的工程判断：在 decode 阶段 P99 是硬 SLO 时，容量因子路由的静态 dispatch 矩阵让 All-to-All 发送缓冲在 kernel launch 前确定，避免了运行时动态分配与 kernel 重编译，P99 可预测；而专家选择路由的负载恒定优势被排序同步的抖动抵消。只有在预填充阶段、token 预算大且因果性可放宽（如非流式批处理）时，专家选择路由的零丢弃才值得考虑。两者的分界线是“decode 还是 prefill”，不是“偏斜还是均匀”。</p>\n\n<h3 id=\"alg-capacity-factor-routing-sec-49\">四十九 · 与块稀疏分组 GEMM 的边界：padding 的算力账</h3>\n<p>块稀疏分组 GEMM 用块级 padding 替代 token 丢弃，思路是把每专家的 token 数向上对齐到固定块大小，GEMM 按块粒度计算。它不丢 token，质量无损，但代价是算力利用率下降：padding 部分参与矩阵乘但不贡献输出。设块大小为 B，专家实际 token 数为 n_e，则有效算力占比为 <span class=\"formula\">$$\\eta=\\frac{\\sum_e n_e}{\\sum_e \\lceil n_e/B\\rceil \\cdot B}$$</span>。当 n_e 远小于 B 时 η 急剧下降，这正是小 batch decode 的常态。</p>\n<p>容量因子路由的算力账则相反：M=capacity 固定，无 padding 浪费，但被丢弃的 token 直接损失质量。两者的取舍可以量化——若 padding 造成的算力浪费折算成延迟增量，仍低于容量因子路由调大 C 带来的显存与带宽增量，则块稀疏分组 GEMM 更优；反之容量因子路由更优。工程上常见的组合是：预填充阶段用块稀疏分组 GEMM 保质量，decode 阶段用容量因子路由保 P99，按阶段切换而非全局二选一。这种混合部署要求调度器能识别 micro-batch 的阶段属性，代价是两套 kernel 的编译产物共存，显存占用略增。</p>\n\n<h3 id=\"alg-capacity-factor-routing-sec-50\">五十 · 适用条件的形式化与标定流程</h3>\n<p>把适用条件写成可执行的标定流程，比定性描述更能指导部署。容量因子路由的标定输入是离线采集的负载分布：对每个 micro-batch 记录各专家 token 数，计算偏斜度与长尾请求占比，然后扫描 C 的候选值，观察 drop rate 与 All-to-All 缓冲大小的权衡曲线。材料给出的锚点是 C=1.25 时 drop rate 通常低于 1%，但这是均值口径；长尾请求（代码、数学）在专家偏斜时 drop rate 显著高于均值，标定时必须按请求类型分层统计，否则均值达标而长尾质量骤降。</p>\n<p>标定的输出是两个阈值：C 的下界由质量容忍度决定，C 的上界由显存与带宽预算决定。若下界高于上界，说明该负载形态不适合容量因子路由，应转向块稀疏分组 GEMM 或专家选择路由。流量分布漂移后，静态 dispatch 矩阵与 GEMM 形状虽仍可预测，但专家利用率下降、吞吐不达预期，此时需要在线重标定 C，重标定的频率取决于分布漂移速度——漂移快则 C 频繁失配，偏小则 drop rate 升高，偏大则缓冲与显存浪费。这是容量因子路由规模上限受负载分布稳定性约束的直接原因。</p>\n\n<h3 id=\"alg-capacity-factor-routing-sec-51\">五十一 · 选型的工程判断落点</h3>\n<p>三族算法的选型最终落在“谁承担不确定性”上：容量因子路由把不确定性转成质量损失，专家选择路由转成因果性妥协，块稀疏分组 GEMM 转成算力浪费。工程判断的顺序应是：先确认质量容忍度能否接受丢弃，不能则排除容量因子路由；再确认因果性能否放宽，不能则排除专家选择路由；最后在容量因子路由与块稀疏分组 GEMM 之间比较显存带宽增量与算力浪费增量，取小者。这个顺序不可颠倒，因为质量与因果性是硬约束，算力是可调预算。</p>\n<p>具体到 Blackwell 部署，容量因子路由的静态形状与 tcgen05 分组 GEMM 的 tile 形状天然契合，M=capacity 固定使 tile 无需运行时重排，这是它在 SM100/SM103 上的结构性优势；块稀疏分组 GEMM 的块对齐则要求 tile 大小与块大小匹配，否则 padding 浪费进一步放大。选型时把“tile 形状是否静态”作为一条硬指标，往往比抽象的质量算力权衡更能快速落位。容量因子路由的单一旋钮 C 让 SLO 与质量的权衡显式化，但也意味着它只适合负载分布相对稳定的 decode 场景；分布漂移频繁时，重标定成本会侵蚀其静态形状的收益。</p>\n\n<h3 id=\"alg-capacity-factor-routing-sec-52\">五十二 · 与相邻算法对照：容量因子路由的选型边界与失效条件</h3>\n<p>把容量因子路由放进同族算法的坐标系里，它的定位非常清楚：它用<strong>丢弃</strong>换取<strong>编译期可静态确定的形状</strong>。相邻的两条路线各自把这一对矛盾推向不同极端。专家选择路由把方向反转——由专家挑 token，使每个专家的负载恒等于 k，从而彻底消除丢弃，但代价是破坏因果性，自回归解码中后续 token 无法影响已生成位置的专家分配，因此只适用于编码器式或非因果的批处理场景。无丢弃块稀疏分组 GEMM 则保留因果性，用块级 padding 把不规则的 token 分布填成规则块，代价是 padding 带来的无效计算与显存占用随负载偏斜程度上升。容量因子路由走第三条路：不反转方向、不做块级填充，而是直接截断，把每专家 token 数压到 <span class=\"formula\">$$\\text{capacity}=\\left\\lceil C\\cdot\\frac{T}{E}\\right\\rceil$$</span> 这个上界上，让 All-to-All 发送缓冲和分组 GEMM 的 M 维在 kernel launch 之前就是常量。选型的第一个判断点是：你的 SLO 是卡在 P99 时延的确定性上，还是卡在输出质量的无损上。前者选容量因子，后者选块稀疏 padding 或专家选择。</p>\n<p>第二个判断点是负载分布的稳定性，这直接决定容量因子是否还能作为“单一旋钮”使用。容量因子按离线标定的负载分布取值，材料给出的锚点是 C=1.25 时 drop rate 通常低于 1%。但这个数字的前提是线上 micro-batch 的专家分布与标定分布同构。一旦流量漂移——例如白天是通用对话、夜间批量涌入代码与数学请求——专家偏斜加剧，长尾请求的 drop rate 会显著高于均值，而被丢弃的 token 走残差旁路，这些请求的输出质量就变得不可控。反过来，若为防漂移把 C 调大，All-to-All 缓冲与显存按 capacity 线性膨胀，静态形状虽仍可预测，但专家利用率下降、吞吐不达预期。这里存在一个可量化的权衡：设漂移后热点专家实际负载为 <span class=\"formula\">$$\\text{drop rate}=\\frac{1}{T}\\sum_{t=1}^{T}\\mathbb{1}\\left[\\text{rank}_e(t)&gt;\\text{capacity}\\right]$$</span>，C 每上调一档，drop rate 下降但缓冲占用上升，二者不可同时优化。工程判断是：把 C 与负载分布的分位数绑定，而不是与均值绑定，并为长尾请求类别单独设一条路由策略。</p>\n<p>第三个判断点是并行拓扑与通信代价。容量因子路由的收益全部来自“形状静态化”：dispatch 矩阵在 kernel launch 前生成，专家侧按固定 M=capacity 做分组 GEMM，tcgen05 的 tile 形状无需运行时重排，因此省掉的是动态分配与 kernel 重编译这两项在 decode 阶段最伤 P99 的开销。但这份收益在跨节点 All-to-All 上会被放大或抵消：capacity 越大，每卡发送缓冲越大，NVLink 域内与跨域流量同比上升；capacity 越小，drop 越多，等效于用质量换带宽。若拓扑是单节点内 NVLink 全互联，缓冲膨胀的代价主要是显存；若是多节点 NVL72 规模的 All-to-All，带宽与尾延迟对 capacity 的敏感度更高，此时宁可取较小的 C 并接受略高的 drop rate。下表给出三族算法在关键维度上的取舍。</p>\n<table class=\"mini\"><thead><tr><th>维度</th><th>容量因子路由</th><th>专家选择路由</th><th>无丢弃块稀疏 GEMM</th></tr></thead><tbody><tr><td>是否丢弃 token</td><td>是，超 capacity 即丢</td><td>否</td><td>否，块级 padding</td></tr><tr><td>因果性</td><td>保持</td><td>破坏</td><td>保持</td></tr><tr><td>形状确定性</td><td>编译期静态</td><td>静态</td><td>依赖块划分，padding 随负载变</td></tr><tr><td>主要系统代价</td><td>质量损失 + 缓冲随 C 膨胀</td><td>不适用自回归解码</td><td>无效计算与显存随偏斜上升</td></tr><tr><td>适用条件</td><td>负载分布可标定、P99 优先</td><td>非因果批处理</td><td>质量无损优先、算力冗余</td></tr></tbody></table>\n<p>最后是失效条件的识别。容量因子路由在三种情形下应当被替换而非调参：其一，长尾请求占比高且专家偏斜是结构性的（代码、数学的 token 分布天然集中到少数专家），drop rate 的均值掩盖了长尾的骤降，此时应改用块稀疏 padding 保住质量；其二，流量分布漂移周期短于标定周期，静态 dispatch 矩阵虽可预测但专家利用率持续走低，吞吐不达预期，应引入在线容量估计或按请求类别分桶标定；其三，拓扑跨域且带宽成为瓶颈，capacity 的任何上调都直接转化为 All-to-All 尾延迟，此时容量因子不再是“单一旋钮”，而是与拓扑绑定的硬约束。规模上限受负载分布稳定性约束，材料未给出具体专家数上限，但判断准则一致：分布越稳、越集中，容量因子越划算；分布越漂、长尾越重，越应让位给不丢 token 的同族算法。</p>\n<table class=\"mini\" data-fig=\"alg-quick\"><caption>速查：这一页回答的五件事</caption><thead><tr><th>项</th><th>内容</th></tr></thead><tbody><tr><td>年份 · 方向</td><td>2021 · MoE路由与容量因子</td></tr><tr><td>解决什么</td><td>MoE 推理中专家负载随批次波动，无容量约束时热点专家溢出导致 All-to-All 缓冲膨胀与长尾时延；需要在不改变…</td></tr><tr><td>一句话机制</td><td>为每个专家设定容量上限 capacity = ceil(capacity_factor × tokens/batch …</td></tr><tr><td>代价与失效</td><td>丢弃 token 直接损失模型质量，长尾请求（如代码、数学）在专家偏斜时 drop rate 显著升高；容量因子需按负载分布离线标定，流量…</td></tr><tr><td>后继</td><td>分块预填与解码 piggyback</td></tr></tbody></table>\n<p class=\"paper-line\">本页对应：algorithms/alg-capacity-factor-routing · 共 8 个片段</p>\n";break;}}})();
